/* GERADO por scripts/montar-miniapps.js a partir de miniapps/fonte/*.html — não editar à mão.
   Páginas-base dos miniapps (bibliotecas e protocolo embutidos, sem valores da instalação) que o
   aplicativo grava na pasta de publicação (js/miniapps-pasta.js) e, no caso da visita à UTI,
   preenche com a lista cifrada dos leitos (js/visita-uti-cifrada.js). */
const MINIAPPS_MODELOS = {"decisao-atb.html":"<!DOCTYPE html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>CCIH — Decisão ATB empírica</title>\n<style>\n* { box-sizing: border-box; } body { font-family: system-ui, sans-serif; margin: 0; background: #f2f4f7; color: #1f2933; }\nheader { background: #0d3f7a; color: #fff; padding: 14px 16px; font-size: 18px; font-weight: 700; }\nmain { padding: 12px; max-width: 560px; margin: 0 auto; }\n.cartao { background: #fff; border: 1px solid #dde3ea; border-radius: 10px; padding: 12px; margin-bottom: 12px; }\nlabel { display: block; font-size: 13px; color: #61707f; margin-top: 8px; }\ninput[type=text], select { width: 100%; font-size: 16px; padding: 9px; border: 1px solid #c3ccd6; border-radius: 8px; background: #fff; }\n.linha { display: flex; gap: 8px; } .linha > div { flex: 1; }\nbutton { font-size: 15px; font-weight: 600; border-radius: 8px; padding: 11px; border: none; cursor: pointer; width: 100%; margin-top: 8px; }\n.principal { background: #0d3f7a; color: #fff; } .secundario { background: #fff; color: #0d3f7a; border: 1px solid #0d3f7a; }\n.excluir { background: none; border: none; color: #b03a2e; font-size: 13px; width: auto; padding: 2px 6px; margin: 0; }\n.suave { color: #61707f; font-size: 13px; }\nul.ajuda { margin: 4px 0 0; padding-left: 18px; color: #61707f; font-size: 12.5px; }\nul.ajuda li { margin: 1px 0; }\n.oculto { display: none; }\n.aviso { border-left: 5px solid #e5b95c; background: #fdf3dd; color: #633806; }\n.aviso p, .aviso li { margin: 6px 0 0; font-size: 14px; }\n.aviso ul { margin: 4px 0 0; padding-left: 18px; }\n.versao { font-size: 12px; font-weight: 400; opacity: .7; }\nh2 { font-size: 17px; margin: 0 0 6px; } h3 { font-size: 13px; color: #61707f; text-transform: uppercase; letter-spacing: .04em; margin: 14px 0 4px; }\n.esq { padding: 8px 0; border-top: 1px solid #eef1f5; }\n.esq:first-child { border-top: none; padding-top: 0; }\n.esq .rot { font-size: 12px; color: #0d3f7a; font-weight: 700; text-transform: uppercase; letter-spacing: .03em; }\n.esq .pos { font-size: 15px; }\nul.exames { margin: 0; padding-left: 18px; font-size: 14px; color: #61707f; }\ndetails { border-top: 1px solid #eef1f5; } details:last-of-type { border-bottom: 1px solid #eef1f5; }\nsummary { padding: 9px 0; font-size: 14px; cursor: pointer; display: flex; justify-content: space-between; gap: 8px; }\nsummary i { color: #61707f; font-style: normal; font-size: 12px; white-space: nowrap; }\ntable { width: 100%; border-collapse: collapse; font-size: 13.5px; margin-bottom: 10px; }\ntd, th { padding: 4px 4px; text-align: left; border-bottom: 1px solid #f1f4f7; } th { font-size: 11px; color: #61707f; text-transform: uppercase; }\ntd.n, th.n { text-align: right; font-variant-numeric: tabular-nums; }\ntd.alta { color: #b03a2e; font-weight: 700; }\n.item { border-bottom: 1px solid #eef1f5; padding: 10px 0; font-size: 14px; }\n.selos span { background: #e7effb; color: #0d3f7a; border-radius: 10px; padding: 2px 8px; font-size: 12px; margin-right: 4px; }\n.selos .enviado { background: #fdf3dd; color: #633806; }\n</style>\n</head>\n<body>\n<header>Decisão de ATB empírica <span class=\"versao\">v06.09d</span></header>\n<main>\n  <div class=\"cartao aviso\" id=\"avisoAbertura\">\n    <strong>Este arquivo precisa ser aberto no navegador.</strong>\n    <p>Você está vendo apenas a pré-visualização do arquivo, que não executa o aplicativo.\n       Toque nos três pontinhos (⋮) no canto da tela e escolha <strong>Abrir com → Chrome</strong>,\n       ou baixe o arquivo e abra-o pela pasta Downloads.</p>\n  </div>\n  <div class=\"cartao aviso\" id=\"avisoArmazenamento\" style=\"display:none\">\n    <strong>Os registros não estão sendo salvos neste aparelho.</strong>\n    <p>Se fechar a página, perde o que registrou. Baixe o arquivo e abra-o pelo navegador.</p>\n  </div>\n\n  <div class=\"cartao\">\n    <p class=\"suave\" id=\"publico\" style=\"margin:0 0 4px\"></p>\n    <div class=\"linha\">\n      <div><label>Prontuário (opcional)</label><input type=\"text\" id=\"prontuario\" inputmode=\"numeric\"></div>\n      <div><label>Quem decide</label><input type=\"text\" id=\"medico\" placeholder=\"seu nome\"></div>\n    </div>\n    <label>Síndrome</label><select id=\"sindrome\"><option value=\"\">escolha a síndrome…</option></select>\n    <p class=\"suave\" id=\"germes\" style=\"margin:6px 0 0\"></p>\n    <div id=\"perguntas\"></div>\n    <button class=\"principal oculto\" id=\"analisar\">Analisar caso</button>\n  </div>\n\n  <div class=\"cartao oculto\" id=\"resultado\"></div>\n\n  <div class=\"cartao\">\n    <div id=\"lista\"></div>\n    <p class=\"suave\" id=\"resumo\"></p>\n    <button class=\"secundario\" id=\"enviar\">Enviar decisões registradas à CCIH</button>\n    <p class=\"suave\">Funciona sem internet: registre agora e envie quando houver rede. Sai só o prontuário — nunca o nome do paciente.</p>\n    <button class=\"excluir\" id=\"limpar\" style=\"width:100%\">Apagar todos os registros do aparelho</button>\n  </div>\n  <p class=\"suave\" id=\"rodape\"></p>\n</main>\n<script>/* Decisão de antibioticoterapia empírica — núcleo puro (roda em Node, testável).\n   As regras vêm do \"Protocolo de Tratamento Empírico de Infecções na Emergência\" da\n   instituição (validado pela CCIH); o motor cruza a resposta do protocolo com os dados LOCAIS do\n   banco: histórico do paciente (MDR, antibióticos e internações recentes) e o\n   antibiograma acumulado do hospital. TUDO é apoio à decisão: a sugestão sai com a\n   justificativa visível e nunca substitui o julgamento do médico assistente.\n\n   Estrutura: cada síndrome tem `perguntas` (o que a tela pergunta) e `decidir(r)` —\n   função pura que devolve { esquemas: [{rotulo, posologia, drogas}], exames, avisos }.\n   `drogas` são nomes canônicos normalizáveis, usados para cruzar com o antibiograma. */\n\nconst REVISAO_PROTOCOLO_ATB = 'Reavaliação obrigatória em 48–72h com as culturas: desescalonar para menor '\n  + 'espectro, migrar para via oral (paciente estável e afebril) ou suspender se culturas negativas '\n  + 'sem outra justificativa clínica.';\n\nconst VANCO = 'Vancomicina 15–20 mg/kg IV de 8/8h ou 12/12h';\n\n/* Definição única de \"risco de MRSA\" (CCIH, 06/09/2026; ATS/IDSA 2019 e IDSA 2014):\n   marcar \"sim\" se qualquer um. Cada síndrome acrescenta os seus reforços. A pergunta\n   `ajuda` aparece na tela abaixo do rótulo. */\nconst RISCO_MRSA_BASE = [\n  'MRSA prévio: infecção ou colonização nos últimos 12 meses',\n  'Internação ≥ 48 h, cirurgia ou antibiótico IV nos últimos 90 dias',\n  'Hemodiálise, institucionalizado (ILPI) ou usuário de droga injetável',\n  'Falha de beta-lactâmico em curso'\n];\nconst riscoMRSA = (id, reforcos) => ({ id, rotulo: 'Risco de MRSA', tipo: 'sim_nao',\n  ajuda: ['Marcar \"sim\" se qualquer um:', ...RISCO_MRSA_BASE, ...reforcos.map(r => r + ' (neste sítio)')] });\n\nconst PROTOCOLO_ATB = {\n  fonte: 'Protocolo de Tratamento Empírico de Infecções na Emergência — SCIH',\n  /* Alterações de conduta validadas pela CCIH depois do documento original. Cada uma é\n     uma decisão registrada aqui até ser incorporada ao texto do protocolo. */\n  adendos: [\n    { data: '2026-09-05', texto: 'Pneumonia aspirativa: ceftriaxona quando não há abscesso pulmonar; ampicilina-sulbactam '\n      + 'reservada à aspirativa com abscesso (4 doses/dia — praticidade pesa na adesão).' },\n    { data: '2026-09-05', texto: 'Pielonefrite/ITU em homem com TFG < 30: amicacina deixa de ser empírico de escolha '\n      + '(nefrotoxicidade). Risco ESBL → ertapenem 1 g IV 1x/dia; alergia a beta-lactâmicos → levofloxacino com dose '\n      + 'ajustada; ciprofloxacino VO ajustado para 24/24h.' },\n    { data: '2026-09-06', texto: 'Função renal: a primeira dose é sempre plena; o ajuste começa na segunda dose, '\n      + 'pela tabela de correção exibida junto do esquema. Nível sérico de vancomicina/amicacina quando disponível; '\n      + 'sem dosagem, corrigir pela tabela e acompanhar creatinina.' },\n    { data: '2026-09-06', texto: 'Risco de MRSA definido (MRSA prévio em 12 meses; internação/cirurgia/ATB IV em 90 dias; '\n      + 'hemodiálise, ILPI ou droga injetável; falha de beta-lactâmico) com reforços por sítio — sem mudança de conduta.' },\n    { data: '2026-09-06', texto: 'Pé diabético infectado acrescentado como síndrome (classificação IWGDF/IDSA 2023): leve VO, '\n      + 'moderada ceftriaxona + metronidazol, grave piperacilina-tazobactam + vancomicina; vancomicina associada se risco de MRSA.' },\n    { data: '2026-09-06', texto: 'Teicoplanina (12 mg/kg 12/12h × 3, depois 1x/dia, IV ou IM) como opção de transição em todo '\n      + 'esquema com vancomicina fora do SNC — curso prolongado, alta precoce, ausência de dosagem sérica.' }\n  ],\n  publico: 'Adultos e adolescentes (>14 anos) com infecção presente na admissão (<48h de internação). '\n    + 'Sepse com foco conhecido segue o protocolo institucional de sepse.',\n  sindromes: [\n\n    {\n      id: 'urinario', rotulo: 'Foco urinário',\n      germes: ['Escherichia coli', 'Klebsiella pneumoniae', 'Proteus mirabilis', 'Enterococcus spp'],\n      perguntas: [\n        /* O protocolo só chama de \"cistite simples\" a da mulher; ITU em homem, mesmo baixa,\n           segue o caminho da pielonefrite (cultura antes da dose, esquema do tratamento 2º). */\n        { id: 'sexo', rotulo: 'Paciente', tipo: 'escolha', opcoes: [['mulher', 'Mulher'], ['homem', 'Homem']] },\n        { id: 'apresentacao', rotulo: 'Apresentação', tipo: 'escolha', opcoes: [\n          ['cistite', 'Cistite (sintomas baixos, sem febre/dor lombar)'], ['pielonefrite', 'Pielonefrite']] },\n        { id: 'internacao', rotulo: 'Necessita internação ou via oral inviável', tipo: 'sim_nao' },\n        { id: 'riscoEsbl', rotulo: 'Risco ESBL: internação, antimicrobiano ou procedimento urológico nos últimos 90 dias', tipo: 'sim_nao' },\n        { id: 'alergiaBL', rotulo: 'Alergia a beta-lactâmicos', tipo: 'sim_nao' },\n        { id: 'tfgBaixa', rotulo: 'TFG < 30 mL/min', tipo: 'sim_nao' }\n      ],\n      decidir(r) {\n        const cistiteSimples = r.apresentacao === 'cistite' && r.sexo !== 'homem';\n        const ituHomemBaixa = r.apresentacao === 'cistite' && r.sexo === 'homem';\n        const exames = cistiteSimples\n          ? ['Cistite simples em mulher: diagnóstico clínico — não coletar exames de rotina.']\n          : ['Urina tipo 1 (EAS) e urocultura com antibiograma ANTES da primeira dose.',\n             '2 pares de hemoculturas se instabilidade hemodinâmica ou febre alta com calafrios.'];\n        const avisosBase = ituHomemBaixa\n          ? ['ITU em homem: o protocolo trata como ITU complicada (mesmo esquema da pielonefrite; nitrofurantoína/fosfomicina não se aplicam).']\n          : [];\n        if (cistiteSimples) {\n          const esquemas = [];\n          if (!r.tfgBaixa) esquemas.push({ rotulo: '1ª escolha', posologia: 'Nitrofurantoína 100 mg VO 12/12h por 5 dias', drogas: ['nitrofurantoina'] });\n          esquemas.push({ rotulo: r.tfgBaixa ? '1ª escolha (TFG < 30: nitrofurantoína contraindicada)' : 'Alternativa',\n            posologia: 'Fosfomicina trometamol 3 g VO, dose única', drogas: ['fosfomicina'] });\n          esquemas.push({ rotulo: 'Segunda linha oral', posologia: 'Amoxicilina + Clavulanato 875/125 mg VO 12/12h por 5–7 dias', drogas: ['amoxicilinaacidoclavulanico'] });\n          return { esquemas, exames, avisos: [] };\n        }\n        /* Adendo CCIH 05/09/2026: com TFG < 30 a amicacina sai do empírico. */\n        const levoAjustado = 'Levofloxacino 750 mg IV no 1º dia, depois 750 mg a cada 48h (TFG 20–49) ou 500 mg a cada 48h (TFG < 20)';\n        if (r.riscoEsbl) {\n          const avisoEsbl = 'Risco ESBL assumido (internação/ATB/procedimento urológico em 90 dias).';\n          if (r.tfgBaixa) {\n            return { esquemas: [{ rotulo: 'Risco ESBL com TFG < 30', posologia: 'Ertapenem 1 g IV 1x/dia', drogas: ['ertapenem'] }],\n              exames, avisos: [...avisosBase, avisoEsbl,\n                'TFG < 30: amicacina evitada (nefrotoxicidade). Ertapenem cobre ESBL, não cobre Pseudomonas nem enterococo.'] };\n          }\n          return { esquemas: [{ rotulo: 'Risco ESBL', posologia: 'Amicacina 15 mg/kg IV 1x/dia', drogas: ['amicacina'] }],\n            exames, avisos: [...avisosBase, avisoEsbl] };\n        }\n        if (r.alergiaBL) {\n          if (r.tfgBaixa) {\n            return { esquemas: [{ rotulo: 'Alergia a beta-lactâmicos com TFG < 30', posologia: levoAjustado, drogas: ['levofloxacino'] }],\n              exames, avisos: [...avisosBase, 'TFG < 30: amicacina evitada (nefrotoxicidade). Se a quinolona não for opção, '\n                + 'amicacina só em dose única com nível sérico — discutir com a CCIH.'] };\n          }\n          return { esquemas: [\n            { rotulo: 'Alergia a beta-lactâmicos', posologia: 'Levofloxacino 750 mg IV 1x/dia', drogas: ['levofloxacino'] },\n            { rotulo: 'Alternativa', posologia: 'Amicacina 15 mg/kg IV 1x/dia', drogas: ['amicacina'] }], exames, avisos: avisosBase };\n        }\n        if (r.internacao) {\n          return { esquemas: [{ rotulo: ituHomemBaixa ? 'ITU em homem, internado' : 'Pielonefrite internada',\n            posologia: 'Ceftriaxona 2 g IV 1x/dia', drogas: ['ceftriaxona'] }], exames, avisos: avisosBase };\n        }\n        const estavel = ituHomemBaixa ? 'ITU em homem, estável (VO)' : 'Pielonefrite estável (VO)';\n        if (r.tfgBaixa) {\n          return { esquemas: [\n            { rotulo: estavel + ' — TFG < 30', posologia: 'Ciprofloxacino 500 mg VO 24/24h por 7 dias', drogas: ['ciprofloxacino'] },\n            { rotulo: 'Alternativa', posologia: levoAjustado.replace('IV', 'VO'), drogas: ['levofloxacino'] }],\n            exames, avisos: [...avisosBase, 'TFG < 30: doses de quinolona ajustadas à função renal.'] };\n        }\n        return { esquemas: [\n          { rotulo: estavel, posologia: 'Ciprofloxacino 500 mg VO 12/12h por 7 dias', drogas: ['ciprofloxacino'] },\n          { rotulo: 'Alternativa', posologia: 'Levofloxacino 750 mg VO 1x/dia por 5 dias', drogas: ['levofloxacino'] }], exames, avisos: avisosBase };\n      }\n    },\n\n    {\n      id: 'respiratorio', rotulo: 'Trato respiratório (PAC)',\n      germes: ['Streptococcus pneumoniae', 'Haemophilus influenzae', 'Moraxella catarrhalis'],\n      perguntas: [\n        { id: 'gravidade', rotulo: 'Gravidade', tipo: 'escolha', opcoes: [\n          ['leve', 'Leve a moderada, via oral viável'], ['internacao', 'Internação (enfermaria/UTI)']] },\n        { id: 'comorbAtb90', rotulo: 'Comorbidades ou antibiótico nos últimos 90 dias', tipo: 'sim_nao' },\n        { id: 'alergiaBLM', rotulo: 'Alergia a beta-lactâmicos/macrolídeos', tipo: 'sim_nao' },\n        { id: 'aspirativa', rotulo: 'Pneumonia aspirativa', tipo: 'sim_nao' },\n        { id: 'abscesso', rotulo: 'Abscesso pulmonar (na aspirativa)', tipo: 'sim_nao' },\n        { id: 'riscoPseudomonas', rotulo: 'Risco para Pseudomonas (bronquiectasias, fibrose cística)', tipo: 'sim_nao' },\n        riscoMRSA('riscoMRSA', ['Pós-influenza', 'Pneumonia cavitária/necrosante', 'Empiema'])\n      ],\n      decidir(r) {\n        const exames = r.gravidade === 'leve'\n          ? ['PAC leve: não coletar exames microbiológicos.']\n          : ['2 pares de hemoculturas e cultura de escarro (se boa qualidade) antes do ATB.',\n             'Derrame parapneumônico: toracocentese diagnóstica imediata (bioquímica, Gram, cultura).'];\n        const esquemas = [];\n        const avisos = [];\n        if (r.alergiaBLM) {\n          esquemas.push({ rotulo: 'Alergia a beta-lactâmicos/macrolídeos', posologia: 'Levofloxacino 750 mg IV/VO 1x/dia por 5 dias', drogas: ['levofloxacino'] });\n          esquemas.push({ rotulo: 'Alternativa', posologia: 'Moxifloxacino 400 mg IV/VO 1x/dia por 5–7 dias', drogas: ['moxifloxacino'] });\n        } else if (r.riscoPseudomonas) {\n          esquemas.push({ rotulo: 'Risco de Pseudomonas', posologia: 'Piperacilina + Tazobactam 4,5 g IV 6/6h + Azitromicina 500 mg IV 1x/dia', drogas: ['piperacilinatazobactam', 'azitromicina'] });\n        } else if (r.aspirativa && r.abscesso) {\n          /* Adendo CCIH 05/09/2026: cobertura anaeróbia só quando há abscesso. */\n          esquemas.push({ rotulo: 'Aspirativa com abscesso pulmonar', posologia: 'Ampicilina + Sulbactam 1,5–3 g IV 6/6h', drogas: ['ampicilinasulbactam'] });\n        } else if (r.aspirativa) {\n          esquemas.push({ rotulo: 'Pneumonia aspirativa sem abscesso', posologia: 'Ceftriaxona 2 g IV 1x/dia', drogas: ['ceftriaxona'] });\n        } else if (r.gravidade === 'internacao') {\n          esquemas.push({ rotulo: 'PAC internada (enfermaria/UTI)', posologia: 'Ceftriaxona 2 g IV 1x/dia + Azitromicina 500 mg IV/VO 1x/dia por 7 dias', drogas: ['ceftriaxona', 'azitromicina'] });\n        } else if (r.comorbAtb90) {\n          esquemas.push({ rotulo: 'Com comorbidades ou ATB em 90 dias', posologia: 'Amoxicilina + Clavulanato 875/125 mg VO 12/12h + Azitromicina 500 mg VO 1x/dia por 7 dias', drogas: ['amoxicilinaacidoclavulanico', 'azitromicina'] });\n        } else {\n          esquemas.push({ rotulo: 'Paciente hígido, sem ATB recente', posologia: 'Amoxicilina 1 g VO 8/8h por 5–7 dias', drogas: ['amoxicilina'] });\n          esquemas.push({ rotulo: 'Alternativa', posologia: 'Azitromicina 500 mg VO 1x/dia por 5 dias', drogas: ['azitromicina'] });\n        }\n        if (r.riscoMRSA) {\n          esquemas.push({ rotulo: 'Risco de MRSA hospitalar — ASSOCIAR', posologia: VANCO, drogas: ['vancomicina'] });\n          avisos.push('Risco de MRSA: vancomicina associada ao esquema básico.');\n        }\n        return { esquemas, exames, avisos };\n      }\n    },\n\n    {\n      id: 'pele', rotulo: 'Pele e partes moles',\n      germes: ['Streptococcus pyogenes', 'Staphylococcus aureus'],\n      perguntas: [\n        { id: 'tipo', rotulo: 'Tipo de infecção', tipo: 'escolha', opcoes: [\n          ['nao_purulenta', 'Não purulenta (celulite/erisipela)'], ['purulenta', 'Purulenta (abscesso / suspeita CA-MRSA)'],\n          ['necrosante', 'Necrosante (ex.: Fournier)']] },\n        { id: 'grave', rotulo: 'Quadro grave / necessidade de internação', tipo: 'sim_nao' },\n        riscoMRSA('riscoMRSAHosp', ['Abscessos múltiplos ou recorrentes', 'Ferida operatória (IRAS)', 'Infecção purulenta grave']),\n        { id: 'alergiaBL', rotulo: 'Alergia a beta-lactâmicos', tipo: 'sim_nao' }\n      ],\n      decidir(r) {\n        const exames = ['Erisipela/celulite típica: diagnóstico clínico, sem culturas de rotina.',\n          'Quadros graves ou de origem hospitalar: 2 pares de hemoculturas.',\n          'Abscesso/lesão purulenta: incisão e drenagem (conduta principal); enviar tecido/aspirado profundo '\n          + 'para Gram e cultura (evitar swab superficial). Revisar vacinação antitetânica.'];\n        if (r.tipo === 'necrosante') {\n          return { esquemas: [{ rotulo: 'Infecção necrosante', posologia: 'Piperacilina + Tazobactam 4,5 g IV 6/6h + ' + VANCO, drogas: ['piperacilinatazobactam', 'vancomicina'] }],\n            exames, avisos: ['Infecção necrosante: avaliação cirúrgica imediata é parte do tratamento.'] };\n        }\n        if (r.alergiaBL) {\n          return { esquemas: [\n            { rotulo: 'Alergia a beta-lactâmicos', posologia: 'Clindamicina 600 mg IV 8/8h', drogas: ['clindamicina'] },\n            { rotulo: 'Alternativa', posologia: VANCO, drogas: ['vancomicina'] }], exames, avisos: [] };\n        }\n        if (r.riscoMRSAHosp) {\n          return { esquemas: [{ rotulo: 'Risco MRSA hospitalar / falha prévia / IRAS', posologia: VANCO + ' (máx. 2 g por infusão)', drogas: ['vancomicina'] }], exames, avisos: [] };\n        }\n        if (r.grave) {\n          return { esquemas: [\n            { rotulo: 'Quadro grave comunitário', posologia: 'Ceftriaxona 2 g IV 1x/dia', drogas: ['ceftriaxona'] },\n            { rotulo: 'Alternativa', posologia: 'Oxacilina 2 g IV 4/4h', drogas: ['oxacilina'] }], exames, avisos: [] };\n        }\n        if (r.tipo === 'purulenta') {\n          return { esquemas: [\n            { rotulo: 'Purulenta leve-moderada (CA-MRSA)', posologia: 'Sulfametoxazol + Trimetoprima 800/160 mg VO 12/12h por 5–7 dias', drogas: ['sulfametoxazoltrimetoprima'] },\n            { rotulo: 'Alternativa', posologia: 'Doxiciclina 100 mg VO 12/12h por 5–7 dias', drogas: ['doxiciclina'] }], exames, avisos: [] };\n        }\n        return { esquemas: [\n          { rotulo: 'Não purulenta leve-moderada', posologia: 'Cefalexina 500 mg–1 g VO 6/6h por 7–10 dias', drogas: ['cefalexina'] },\n          { rotulo: 'Alternativa', posologia: 'Amoxicilina 500 mg–1 g VO 8/8h por 7–10 dias', drogas: ['amoxicilina'] }], exames, avisos: [] };\n      }\n    },\n\n    {\n      /* Acrescentado pela CCIH em 06/09/2026 (não consta do documento original). Classificação\n         IWGDF/IDSA 2023; esquemas seguem a padronização da casa e a preferência por 1x/dia. */\n      id: 'pe_diabetico', rotulo: 'Pé diabético infectado',\n      germes: ['Staphylococcus aureus', 'Streptococcus spp', 'Escherichia coli', 'Klebsiella pneumoniae', 'Pseudomonas aeruginosa'],\n      perguntas: [\n        { id: 'gravidade', rotulo: 'Gravidade (IWGDF/IDSA)', tipo: 'escolha', opcoes: [\n          ['leve', 'Leve — eritema ≤ 2 cm da úlcera, só pele/subcutâneo, sem sinais sistêmicos'],\n          ['moderada', 'Moderada — eritema > 2 cm ou estrutura profunda (abscesso, fasciíte, osteomielite, artrite), sem sinais sistêmicos'],\n          ['grave', 'Grave — sinais sistêmicos (SIRS) ou instabilidade']] },\n        { id: 'osteomielite', rotulo: 'Suspeita de osteomielite (osso exposto, probe-to-bone positivo, úlcera > 2 cm ou > 6 semanas, imagem)', tipo: 'sim_nao' },\n        riscoMRSA('riscoMRSA', ['Úlcera crônica com antibióticos repetidos', 'Amputação ou cirurgia prévia no pé']),\n        { id: 'alergiaBL', rotulo: 'Alergia a beta-lactâmicos', tipo: 'sim_nao' }\n      ],\n      decidir(r) {\n        const exames = ['Cultura de tecido profundo APÓS desbridamento (curetagem/biópsia) — swab superficial não orienta.',\n          'Radiografia do pé em todos; probe-to-bone; PCR/VHS. Osteomielite: biópsia óssea antes do ATB se estável.',\n          'Moderada/grave: 2 pares de hemoculturas. Avaliar perfusão (pulsos/ITB) e necessidade de desbridamento/drenagem — parte do tratamento.'];\n        const avisos = [];\n        if (r.osteomielite) avisos.push('Osteomielite suspeita: tratamento prolongado (≥ 6 semanas sem ressecção) — discutir com CCIH e ortopedia/vascular.');\n        const esquemas = [];\n        if (r.gravidade === 'grave') {\n          if (r.alergiaBL) {\n            esquemas.push({ rotulo: 'Grave, alergia a beta-lactâmicos', posologia: VANCO + ' + Ciprofloxacino 400 mg IV 12/12h + Metronidazol 500 mg IV 8/8h', drogas: ['vancomicina', 'ciprofloxacino', 'metronidazol'] });\n          } else {\n            esquemas.push({ rotulo: 'Grave (sinais sistêmicos)', posologia: 'Piperacilina + Tazobactam 4,5 g IV 6/6h + ' + VANCO, drogas: ['piperacilinatazobactam', 'vancomicina'] });\n          }\n          avisos.push('Grave: cobertura ampla (Gram-positivos, Gram-negativos, anaeróbios, MRSA) até cultura profunda — desescalonar em 48–72h.');\n        } else if (r.gravidade === 'moderada') {\n          if (r.alergiaBL) {\n            esquemas.push({ rotulo: 'Moderada, alergia a beta-lactâmicos', posologia: 'Ciprofloxacino 400 mg IV 12/12h + Clindamicina 600 mg IV 8/8h', drogas: ['ciprofloxacino', 'clindamicina'] });\n          } else {\n            esquemas.push({ rotulo: 'Moderada', posologia: 'Ceftriaxona 2 g IV 1x/dia + Metronidazol 500 mg IV 8/8h', drogas: ['ceftriaxona', 'metronidazol'] });\n            esquemas.push({ rotulo: 'Alternativa', posologia: 'Ampicilina + Sulbactam 3 g IV 6/6h', drogas: ['ampicilinasulbactam'] });\n          }\n          if (r.riscoMRSA) {\n            esquemas.push({ rotulo: 'Risco de MRSA — ASSOCIAR', posologia: VANCO, drogas: ['vancomicina'] });\n          }\n        } else {\n          if (r.alergiaBL) {\n            esquemas.push({ rotulo: 'Leve, alergia a beta-lactâmicos', posologia: 'Clindamicina 300–450 mg VO 8/8h por 1–2 semanas', drogas: ['clindamicina'] });\n          } else if (r.riscoMRSA) {\n            esquemas.push({ rotulo: 'Leve com risco de MRSA', posologia: 'Sulfametoxazol + Trimetoprima 800/160 mg VO 12/12h por 1–2 semanas (+ Cefalexina se celulite estreptocócica)', drogas: ['sulfametoxazoltrimetoprima'] });\n            esquemas.push({ rotulo: 'Alternativa', posologia: 'Doxiciclina 100 mg VO 12/12h por 1–2 semanas', drogas: ['doxiciclina'] });\n          } else {\n            esquemas.push({ rotulo: 'Leve', posologia: 'Cefalexina 500 mg–1 g VO 6/6h por 1–2 semanas', drogas: ['cefalexina'] });\n            esquemas.push({ rotulo: 'Alternativa', posologia: 'Amoxicilina + Clavulanato 875/125 mg VO 12/12h por 1–2 semanas', drogas: ['amoxicilinaacidoclavulanico'] });\n          }\n        }\n        return { esquemas, exames, avisos };\n      }\n    },\n\n    {\n      id: 'snc', rotulo: 'SNC (meningoencefalite bacteriana)',\n      germes: ['Streptococcus pneumoniae', 'Neisseria meningitidis', 'Haemophilus influenzae'],\n      perguntas: [\n        { id: 'listeria', rotulo: 'Idade > 50 anos, gestante ou imunocomprometido', tipo: 'sim_nao' },\n        { id: 'posNeuro', rotulo: 'Pós-neurocirurgia, derivação ou trauma craniano (IRAS)', tipo: 'sim_nao' }\n      ],\n      decidir(r) {\n        const exames = ['Punção lombar imediata (salvo contraindicação): quimiocitológico, bioquímica, Gram, cultura; '\n          + 'glicemia sérica simultânea.', '2 pares de hemoculturas imediatamente.',\n          'NÃO atrasar o ATB por logística da PL. Isolamento respiratório nas primeiras 24h e notificação imediata à SCIH/NHE.'];\n        if (r.posNeuro) {\n          return { esquemas: [{ rotulo: 'Pós-neurocirurgia/derivação/TCE', posologia: 'Ceftazidima 2 g IV 8/8h + ' + VANCO, drogas: ['ceftazidima', 'vancomicina'] }], exames, avisos: [] };\n        }\n        const esquemas = [\n          { rotulo: 'Corticoterapia adjuvante', posologia: 'Dexametasona 0,15 mg/kg IV 6/6h por 4 dias — primeira dose antes ou junto do ATB', drogas: [] },\n          { rotulo: 'Esquema padrão', posologia: 'Ceftriaxona 2 g IV 12/12h + ' + VANCO, drogas: ['ceftriaxona', 'vancomicina'] }];\n        if (r.listeria) {\n          esquemas.push({ rotulo: 'Cobertura de Listeria — ASSOCIAR', posologia: 'Ampicilina 2 g IV 4/4h', drogas: ['ampicilina'] });\n        }\n        return { esquemas, exames, avisos: [] };\n      }\n    },\n\n    {\n      id: 'abdominal', rotulo: 'Intra-abdominal',\n      germes: ['Escherichia coli', 'Klebsiella pneumoniae'],\n      perguntas: [\n        { id: 'alergiaBL', rotulo: 'Alergia a beta-lactâmicos', tipo: 'sim_nao' },\n        { id: 'riscoMDR', rotulo: 'Risco de multirresistência (ESBL / IRAS)', tipo: 'sim_nao' }\n      ],\n      decidir(r) {\n        const exames = ['Leve/moderado com controle cirúrgico rápido: sem culturas.',\n          'Grave/peritonite difusa: 2 pares de hemoculturas.',\n          'Drenagem cirúrgica/abscesso: líquido peritoneal para Gram e cultura (pode semear em frasco de hemocultura, rotulado).'];\n        if (r.riscoMDR) {\n          return { esquemas: [{ rotulo: 'Risco de multirresistência (ESBL/IRAS)', posologia: 'Piperacilina + Tazobactam 4,5 g IV 6/6h', drogas: ['piperacilinatazobactam'] }], exames, avisos: [] };\n        }\n        if (r.alergiaBL) {\n          return { esquemas: [{ rotulo: 'Alergia a beta-lactâmicos', posologia: 'Ciprofloxacino 400 mg IV 12/12h + Metronidazol 500 mg IV 8/8h', drogas: ['ciprofloxacino', 'metronidazol'] }], exames, avisos: [] };\n        }\n        return { esquemas: [\n          { rotulo: 'Infecção comunitária', posologia: 'Ceftriaxona 2 g IV 1x/dia + Metronidazol 500 mg IV 8/8h (6/6h se peritonite grave)', drogas: ['ceftriaxona', 'metronidazol'] },\n          { rotulo: 'Transição VO (alta)', posologia: 'Amoxicilina + Clavulanato 875/125 mg VO 12/12h', drogas: ['amoxicilinaacidoclavulanico'] }], exames, avisos: [] };\n      }\n    },\n\n    {\n      id: 'osteoarticular', rotulo: 'Osteoarticular (artrite séptica / osteomielite)',\n      germes: ['Staphylococcus aureus', 'Streptococcus spp'],\n      perguntas: [\n        { id: 'idosoComorb', rotulo: 'Idoso, diabético ou comorbidades crônicas', tipo: 'sim_nao' },\n        { id: 'posTrauma', rotulo: 'Pós-trauma ou procedimento cirúrgico prévio (IRAS)', tipo: 'sim_nao',\n          ajuda: ['Inclui prótese ou material de síntese e pós-operatório recente — risco de MRSA e Pseudomonas.'] },\n        { id: 'alergiaBL', rotulo: 'Alergia a beta-lactâmicos', tipo: 'sim_nao' },\n        { id: 'riscoGramNeg', rotulo: 'Fator de risco para Gram-negativos', tipo: 'sim_nao' }\n      ],\n      decidir(r) {\n        const exames = ['2 pares de hemoculturas obrigatórios para todos.',\n          'Artrite séptica: artrocentese imediata — celularidade, glicose, Gram, cultura (pode semear em frasco de hemocultura).',\n          'Osteomielite: biópsia óssea/fragmento profundo em centro cirúrgico (evitar secreção de fístula superficial).'];\n        if (r.posTrauma) {\n          return { esquemas: [{ rotulo: 'Pós-trauma / pós-operatório (risco MRSA/Pseudomonas)', posologia: 'Ceftazidima 2 g IV 8/8h + ' + VANCO, drogas: ['ceftazidima', 'vancomicina'] }], exames, avisos: [] };\n        }\n        if (r.alergiaBL) {\n          const esquemas = [\n            { rotulo: 'Alergia a beta-lactâmicos', posologia: 'Clindamicina 600 mg IV 8/8h', drogas: ['clindamicina'] },\n            { rotulo: 'Alternativa', posologia: 'Vancomicina 15–20 mg/kg IV 12/12h', drogas: ['vancomicina'] }];\n          if (r.riscoGramNeg) esquemas.push({ rotulo: 'Risco de Gram-negativos — ASSOCIAR', posologia: 'Ciprofloxacino 400 mg IV 12/12h', drogas: ['ciprofloxacino'] });\n          return { esquemas, exames, avisos: [] };\n        }\n        if (r.idosoComorb) {\n          return { esquemas: [\n            { rotulo: 'Idoso/diabético/comorbidades', posologia: 'Ceftriaxona 2 g IV 1x/dia', drogas: ['ceftriaxona'] },\n            { rotulo: 'Alternativa', posologia: 'Ampicilina + Sulbactam 3 g IV 6/6h', drogas: ['ampicilinasulbactam'] }], exames, avisos: [] };\n        }\n        return { esquemas: [{ rotulo: 'Adulto jovem e hígido', posologia: 'Oxacilina 2 g IV 4/4h', drogas: ['oxacilina'] }], exames, avisos: [] };\n      }\n    },\n\n    {\n      id: 'biliar', rotulo: 'Trato biliar (colecistite/colangite)',\n      germes: ['Escherichia coli', 'Klebsiella pneumoniae', 'Enterococcus spp'],\n      perguntas: [\n        { id: 'grave', rotulo: 'Quadro grave, colangite supurativa obstrutiva ou manipulação biliar prévia', tipo: 'sim_nao' },\n        { id: 'alergiaBL', rotulo: 'Alergia a beta-lactâmicos', tipo: 'sim_nao' }\n      ],\n      decidir(r) {\n        const exames = ['2 pares de hemoculturas se colangite ou repercussão sistêmica (febre/calafrios).',\n          'CPRE/cirurgia biliar: enviar bile aspirada para cultura.'];\n        if (r.grave) {\n          return { esquemas: [{ rotulo: 'Grave / obstrutiva / manipulação prévia', posologia: 'Piperacilina + Tazobactam 4,5 g IV 6/6h', drogas: ['piperacilinatazobactam'] }], exames, avisos: [] };\n        }\n        if (r.alergiaBL) {\n          return { esquemas: [{ rotulo: 'Alergia a beta-lactâmicos', posologia: 'Ciprofloxacino 400 mg IV 12/12h + Metronidazol 500 mg IV 8/8h', drogas: ['ciprofloxacino', 'metronidazol'] }], exames, avisos: [] };\n        }\n        return { esquemas: [\n          { rotulo: 'Leve-moderado comunitário', posologia: 'Ceftriaxona 2 g IV 1x/dia + Metronidazol 500 mg IV 8/8h', drogas: ['ceftriaxona', 'metronidazol'] },\n          { rotulo: 'Monoterapia alternativa', posologia: 'Ampicilina + Sulbactam 3 g IV 6/6h', drogas: ['ampicilinasulbactam'] }], exames, avisos: [] };\n      }\n    },\n\n    {\n      id: 'sepse_fi', rotulo: 'Sepse de foco indeterminado',\n      germes: ['Escherichia coli', 'Klebsiella pneumoniae', 'Staphylococcus aureus'],\n      perguntas: [\n        { id: 'riscoMDR', rotulo: 'Fatores de risco para multirresistentes / IRAS', tipo: 'sim_nao' },\n        { id: 'choque', rotulo: 'Choque séptico', tipo: 'sim_nao' }\n      ],\n      decidir(r) {\n        const exames = ['2 pares de hemoculturas de sítios diferentes IMEDIATAMENTE — meta: coleta e primeira dose na 1ª hora.',\n          'Exames rápidos conforme suspeita (urina 1, RX tórax, TC) sem postergar o antibiótico.'];\n        if (r.riscoMDR) {\n          return { esquemas: [\n            { rotulo: 'Com risco de MDR/IRAS', posologia: 'Piperacilina + Tazobactam 4,5 g IV 6/6h + ' + VANCO, drogas: ['piperacilinatazobactam', 'vancomicina'] },\n            { rotulo: 'Alternativa', posologia: 'Cefepima 2 g IV 8/8h + ' + VANCO, drogas: ['cefepima', 'vancomicina'] }], exames, avisos: [] };\n        }\n        const posologia = 'Ceftriaxona 2 g IV 1x/dia' + (r.choque ? ' — considerar dose de ataque 2 g IV 12/12h no primeiro dia (choque séptico)' : '');\n        return { esquemas: [{ rotulo: 'Sepse comunitária pura', posologia, drogas: ['ceftriaxona'] }], exames, avisos: [] };\n      }\n    }\n  ]\n};\n\n/* ---- Teicoplanina para curso prolongado (CCIH, 06/09/2026) ----\n   Todo esquema com vancomicina fora do SNC ganha a opção de transição: 1x/dia, IM possível,\n   menos nefrotóxica e menos dependente de nível sérico (que a casa não tem). Não é o\n   empírico inicial — a carga de 3 dias atrasa o alvo; entra quando o curso vai ser longo\n   (osteomielite, pé diabético, prótese) ou para alta precoce. Aplicado por embrulho sobre\n   `decidir`, para valer em toda síndrome sem duplicar a regra. */\nconst TEICOPLANINA = { rotulo: 'Curso prolongado (≥ 2 semanas) ou transição para 1x/dia / IM',\n  posologia: 'Teicoplanina 12 mg/kg IV ou IM 12/12h por 3 doses, depois 12 mg/kg 1x/dia (no lugar da vancomicina; não em SNC)',\n  drogas: ['teicoplanina'] };\nfor (const sindrome of PROTOCOLO_ATB.sindromes) {\n  if (sindrome.id === 'snc') continue;\n  const original = sindrome.decidir;\n  sindrome.decidir = function (r) {\n    const decisao = original.call(this, r);\n    if (decisao.esquemas.some(e => (e.drogas || []).includes('vancomicina'))) decisao.esquemas.push(TEICOPLANINA);\n    return decisao;\n  };\n}\n\n/* ---- Ajuste à função renal ----\n   Regra do protocolo (CCIH, 06/09/2026): a PRIMEIRA dose é sempre plena — dose de ataque —\n   qualquer que seja a função renal; o ajuste começa na segunda dose. Faixas em TFG/ClCr\n   (mL/min), adulto. Só constam as drogas dos esquemas que precisam de ajuste; as demais\n   (ceftriaxona, metronidazol, azitromicina, clindamicina, doxiciclina, oxacilina,\n   moxifloxacino, fosfomicina) não ajustam. Referência: bula/Sanford — conferir com a\n   farmácia em diálise. */\nconst ORIENTACAO_RENAL = 'Primeira dose sempre plena (dose de ataque), qualquer que seja a função renal. '\n  + 'O ajuste começa na SEGUNDA dose, pela TFG/ClCr. Vancomicina e amicacina: nível sérico QUANDO DISPONÍVEL; '\n  + 'sem dosagem, corrigir pela tabela e acompanhar creatinina a cada 48 h.';\n\nconst AJUSTE_RENAL = {\n  vancomicina: { rotulo: 'Vancomicina', nota: 'Ataque 20–25 mg/kg (máx. 2 g). Se houver dosagem: vale 15–20 mg/L antes da 4ª dose. '\n    + 'Sem dosagem: tabela + creatinina a cada 48 h.', faixas: [\n    ['> 90', '15–20 mg/kg 8/8h a 12/12h'], ['50–90', '15–20 mg/kg 12/12h'], ['30–49', '15–20 mg/kg 24/24h'],\n    ['15–29', '15–20 mg/kg 48/48h'], ['< 15 / diálise', 'ataque 15–20 mg/kg; depois 500 mg–1 g após cada sessão de diálise']] },\n  amicacina: { rotulo: 'Amicacina', nota: '1ª dose 15 mg/kg plena. Se houver dosagem: vale < 5 mg/L antes de redosar. '\n    + 'Sem dosagem: tabela, curso curto (≤ 5–7 dias) e creatinina a cada 48 h; com TFG < 30 preferir alternativa.', faixas: [\n    ['≥ 60', '15 mg/kg 24/24h'], ['40–59', '15 mg/kg 36/36h'], ['20–39', '15 mg/kg 48/48h'],\n    ['10–19', '7,5 mg/kg 48/48h'], ['< 10 / diálise', '7,5 mg/kg após cada sessão de diálise']] },\n  ciprofloxacino: { rotulo: 'Ciprofloxacino', faixas: [\n    ['≥ 30', 'sem ajuste'], ['5–29', 'IV 400 mg 24/24h · VO 250–500 mg 24/24h'], ['diálise', 'como 5–29, dose após a sessão']] },\n  levofloxacino: { rotulo: 'Levofloxacino', faixas: [\n    ['≥ 50', '750 mg 24/24h'], ['20–49', '750 mg 48/48h'], ['10–19 / diálise', '750 mg no 1º dia, depois 500 mg 48/48h']] },\n  piperacilinatazobactam: { rotulo: 'Piperacilina-tazobactam', faixas: [\n    ['> 40', '4,5 g 6/6h'], ['20–40', '3,375 g 6/6h'], ['< 20', '2,25 g 6/6h'], ['diálise', '2,25 g 8/8h + 0,75 g após a sessão']] },\n  cefepima: { rotulo: 'Cefepima', faixas: [\n    ['> 60', '2 g 8/8h'], ['30–60', '2 g 12/12h'], ['11–29', '2 g 24/24h'], ['< 11 / diálise', '1 g 24/24h (após a sessão)']] },\n  ceftazidima: { rotulo: 'Ceftazidima', faixas: [\n    ['> 50', '2 g 8/8h'], ['31–50', '1 g 12/12h'], ['16–30', '1 g 24/24h'], ['6–15', '500 mg 24/24h'], ['< 6 / diálise', '500 mg 48/48h (1 g após a sessão)']] },\n  meropenem: { rotulo: 'Meropenem', faixas: [\n    ['> 50', '1 g 8/8h'], ['26–50', '1 g 12/12h'], ['10–25', '500 mg 12/12h'], ['< 10 / diálise', '500 mg 24/24h (após a sessão)']] },\n  ertapenem: { rotulo: 'Ertapenem', faixas: [\n    ['> 30', '1 g 24/24h'], ['≤ 30 / diálise', '500 mg 24/24h (+150 mg após a sessão se a dose foi < 6h antes)']] },\n  ampicilina: { rotulo: 'Ampicilina', faixas: [\n    ['> 50', '2 g 4/4h'], ['10–50', '2 g 6/6h a 12/12h'], ['< 10 / diálise', '2 g 12/12h a 24/24h (após a sessão)']] },\n  ampicilinasulbactam: { rotulo: 'Ampicilina-sulbactam', faixas: [\n    ['≥ 30', '1,5–3 g 6/6h'], ['15–29', '1,5–3 g 12/12h'], ['5–14 / diálise', '1,5–3 g 24/24h (após a sessão)']] },\n  amoxicilinaacidoclavulanico: { rotulo: 'Amoxicilina-clavulanato', faixas: [\n    ['≥ 30', '875/125 mg 12/12h'], ['10–29', 'não usar 875 mg: 500/125 mg 12/12h'], ['< 10 / diálise', '500/125 mg 24/24h (após a sessão)']] },\n  sulfametoxazoltrimetoprima: { rotulo: 'Sulfametoxazol-trimetoprima', faixas: [\n    ['> 30', 'dose plena'], ['15–30', 'metade da dose'], ['< 15', 'evitar']] },\n  cefalexina: { rotulo: 'Cefalexina', faixas: [\n    ['≥ 60', '500 mg–1 g 6/6h'], ['30–59', 'máx. 1 g 8/8h'], ['15–29', '250–500 mg 8/8h a 12/12h'], ['5–14 / diálise', '250–500 mg 24/24h (após a sessão)']] },\n  nitrofurantoina: { rotulo: 'Nitrofurantoína', faixas: [['≥ 30', '100 mg 12/12h'], ['< 30', 'contraindicada']] },\n  teicoplanina: { rotulo: 'Teicoplanina', nota: 'As 3 doses de ataque (12/12h) não se ajustam; ajustar a partir do 4º dia.', faixas: [\n    ['> 60', '12 mg/kg 24/24h'], ['40–60', '12 mg/kg 48/48h'], ['< 40 / diálise', '12 mg/kg 72/72h']] }\n};\n\n/* Tabela de ajuste só das drogas presentes nos esquemas sugeridos. */\nfunction ajusteRenalDosEsquemas(esquemas) {\n  const drogas = [...new Set((esquemas || []).flatMap(e => e.drogas || []))];\n  return drogas.map(d => AJUSTE_RENAL[d]).filter(Boolean);\n}\n\n/* Sinônimos de grafia entre o protocolo e o laboratório (já normalizados). */\nconst SINONIMOS_DROGA_ATB = {\n  ceftriaxone: 'ceftriaxona', cefepime: 'cefepima', ciprofloxacina: 'ciprofloxacino',\n  amoxicilinaclavulanato: 'amoxicilinaacidoclavulanico', piperacilinaetazobactam: 'piperacilinatazobactam',\n  trimetoprimasulfametoxazol: 'sulfametoxazoltrimetoprima'\n};\nfunction drogaCanonicaATB(nome) {\n  const n = normalizarTexto(nome);\n  return SINONIMOS_DROGA_ATB[n] || n;\n}\n\n/* ---- Contexto local do paciente ----\n   O que o banco já sabe e muda a decisão: multirresistentes isolados nos últimos 12\n   meses, antibióticos nos últimos 90 dias e internação recente. É daqui que os fatores\n   de risco saem pré-marcados na tela — o médico confirma ou corrige. */\nfunction contextoLocalDoPaciente(bancos, prontuario, hoje) {\n  const chave = normalizarProntuario(prontuario);\n  if (!chave) return null;\n  const corte90 = new Date(Date.parse(hoje + 'T00:00:00Z') - 90 * 86400000).toISOString().slice(0, 10);\n  const corte365 = new Date(Date.parse(hoje + 'T00:00:00Z') - 365 * 86400000).toISOString().slice(0, 10);\n  const sens = indiceSensibilidade(bancos);\n\n  const doPaciente = ((bancos.culturas || {}).culturas || [])\n    .filter(c => normalizarProntuario(c.Prontuario) === chave && String(c.DataColeta).slice(0, 10) >= corte365);\n  const mdr = doPaciente\n    .map(c => ({ data: String(c.DataColeta).slice(0, 10), germe: c.Microrganismo, material: c.Material,\n      mecanismo: mecanismoDaCultura(c, sens) }))\n    .filter(x => x.mecanismo)\n    .sort((a, b) => b.data.localeCompare(a.data));\n\n  const cursos = cursosDeAntibiotico(((bancos.antibioticos || {}).prescricoes || [])\n    .filter(p => normalizarProntuario(p.Prontuario) === chave));\n  const atb90 = [...new Set(cursos.filter(c => c.fim >= corte90).map(c => c.Antibiotico))];\n\n  const internacao90 = ((bancos.pacientes || {}).internacoes || []).some(i =>\n    normalizarProntuario(i.Prontuario) === chave\n    && (!String(i.DataAlta || '').trim() || String(i.DataAlta).slice(0, 10) >= corte90));\n\n  const alertas = [];\n  for (const x of mdr.slice(0, 5)) {\n    alertas.push(`Já isolou ${x.germe} (${x.mecanismo}) em ${x.data} (${x.material || 'material não informado'}) — `\n      + 'o esquema empírico deve considerar essa cobertura; na dúvida, discutir com a CCIH.');\n  }\n  if (atb90.length) alertas.push(`Antibióticos nos últimos 90 dias: ${atb90.join(', ')}.`);\n  if (internacao90) alertas.push('Internação nos últimos 90 dias.');\n\n  return { mdr, atb90, internacao90, culturasRecentes: doPaciente.length, alertas,\n    riscoPresumido: Boolean(mdr.length || atb90.length || internacao90) };\n}\n\n/* ---- Antibiograma acumulado local por germe ----\n   Fatia do banco para os germes prováveis da síndrome: % de resistência por antibiótico,\n   com n testado. É o que corrige o consenso com a realidade da casa. */\nfunction antibiogramaLocalPorGermes(bancos, germes, hoje, meses) {\n  const corte = new Date(Date.parse(hoje + 'T00:00:00Z') - (meses || 24) * 30 * 86400000).toISOString().slice(0, 10);\n  const sens = indiceSensibilidade(bancos);\n  const resultado = [];\n  for (const germe of (germes || [])) {\n    const partes = normalizarTexto(germe).replace(/spp?$/, '');\n    const culturas = ((bancos.culturas || {}).culturas || []).filter(c =>\n      String(c.DataColeta).slice(0, 10) >= corte\n      && normalizarTexto(c.Microrganismo).includes(partes)\n      && !['Água', 'Leite', 'Não é cultura'].includes(String(c.AvaliacaoCCIH || '').trim()));\n    const porDroga = new Map();\n    for (const c of culturas) {\n      const vistos = new Set();\n      for (const s of (sens.get(c.ID_Cultura) || [])) {\n        if (!['R', 'S', 'I'].includes(s.Resultado)) continue;\n        const droga = drogaCanonicaATB(s.Antibiotico);\n        if (vistos.has(droga)) continue;\n        vistos.add(droga);\n        if (!porDroga.has(droga)) porDroga.set(droga, { rotulo: s.Antibiotico, testados: 0, resistentes: 0 });\n        const conta = porDroga.get(droga);\n        conta.testados++;\n        if (s.Resultado === 'R') conta.resistentes++;\n      }\n    }\n    const linhas = [...porDroga.entries()]\n      .map(([droga, c]) => ({ droga, rotulo: c.rotulo, testados: c.testados,\n        pctR: Math.round(c.resistentes / c.testados * 100) }))\n      .sort((a, b) => b.testados - a.testados);\n    resultado.push({ germe, culturas: culturas.length, linhas });\n  }\n  return resultado;\n}\n\n/* Cruza o esquema sugerido com o antibiograma local: droga com resistência alta nos\n   germes prováveis vira aviso com número e n — o dado local corrigindo o consenso. */\nfunction avisosDeResistenciaLocal(esquemas, antibiograma, periodoTexto) {\n  const periodo = periodoTexto || 'nos últimos 24 meses';\n  const avisos = [];\n  for (const esquema of (esquemas || [])) {\n    for (const droga of (esquema.drogas || [])) {\n      for (const bloco of (antibiograma || [])) {\n        const linha = (bloco.linhas || []).find(l => l.droga === droga);\n        if (!linha || linha.testados < 20 || linha.pctR < 30) continue;\n        avisos.push(`Atenção — dado LOCAL: ${bloco.germe} tem ${linha.pctR}% de resistência a `\n          + `${linha.rotulo} (n=${linha.testados} testados ${periodo}). `\n          + 'Considerar alternativa ou coleta de cultura antes da primeira dose.');\n      }\n    }\n  }\n  return [...new Set(avisos)];\n}\n\n/* ---- Antibiograma consolidado para o miniapp ----\n   O celular não carrega o banco: leva um recorte FECHADO (ex.: jun/2024–jun/2026) do\n   antibiograma dos germes do protocolo, calculado aqui no computador da CCIH e embutido\n   no HTML pelo montador. Só agregados (n testados e %R) — nenhum dado de paciente sai. */\nfunction antibiogramaConsolidado(bancos, germes, de, ate) {\n  const culturas = ((bancos.culturas || {}).culturas || []).filter(c => {\n    const d = String(c.DataColeta).slice(0, 10);\n    return d >= de && d <= ate;\n  });\n  const recorte = { culturas: { culturas, sensibilidade: (bancos.culturas || {}).sensibilidade || [] } };\n  /* O corte por meses de antibiogramaLocalPorGermes fica folgado: o recorte por data já foi feito. */\n  const meses = Math.ceil((Date.parse(ate + 'T00:00:00Z') - Date.parse(de + 'T00:00:00Z')) / (30 * 86400000)) + 1;\n  return { periodo: { de, ate }, germes: antibiogramaLocalPorGermes(recorte, germes, ate, meses) };\n}\n\nif (typeof module !== 'undefined' && module.exports) {\n  module.exports = { PROTOCOLO_ATB, REVISAO_PROTOCOLO_ATB, ORIENTACAO_RENAL, AJUSTE_RENAL, ajusteRenalDosEsquemas,\n    contextoLocalDoPaciente, antibiogramaLocalPorGermes, antibiogramaConsolidado, avisosDeResistenciaLocal, drogaCanonicaATB };\n}\n</script>\n\n<script>\nconst CHAVE = 'ccih.decisao.atb.v1';\nconst CHAVE_MEDICO = 'ccih.decisao.atb.medico';\nconst EMAIL_DESTINO = 'defina-o-email-da-ccih@exemplo.br';\nconst ENVIO_URL = '';\nconst ENVIO_SEGREDO = 'troque-este-segredo';\nconst $ = id => document.getElementById(id);\n\n/* O aviso de abertura fica visível por padrão e some assim que o script roda: se a página\n   for aberta num visualizador que não executa JavaScript (a pré-visualização do Google\n   Drive, por exemplo), o usuário lê o que fazer em vez de encontrar um formulário morto. */\n$('avisoAbertura').style.display = 'none';\n\n/* Esses mesmos visualizadores rodam a página numa caixa sem armazenamento, e aí tocar em\n   localStorage lança exceção. Sem esta proteção o miniapp morria na primeira linha. */\nlet armazenamentoOk = true;\nconst guardadoNaMemoria = {};\nfunction lerLocal(chave) {\n  try { return localStorage.getItem(chave); }\n  catch (e) { armazenamentoOk = false; return chave in guardadoNaMemoria ? guardadoNaMemoria[chave] : null; }\n}\nfunction gravarLocal(chave, valor) {\n  try { localStorage.setItem(chave, valor); }\n  catch (e) { armazenamentoOk = false; guardadoNaMemoria[chave] = valor; }\n}\nfunction conferirArmazenamento() { $('avisoArmazenamento').style.display = armazenamentoOk ? 'none' : ''; }\n\n/* Motor do protocolo (js/protocolo-atb.js) entra pelo montador. O antibiograma\n   consolidado do hospital é OPCIONAL (montar com --com-antibiograma): sem ele, o miniapp\n   é o protocolo puro — recomendações de consenso, sem avisos de resistência local. É o\n   modo inicial: gera dados de uso (decisões registradas) enquanto o banco acumula painel. */\nconst AB = typeof ANTIBIOGRAMA_CONSOLIDADO !== 'undefined' ? ANTIBIOGRAMA_CONSOLIDADO : null;\nif (typeof PROTOCOLO_ATB === 'undefined') {\n  document.querySelector('main').prepend(Object.assign(document.createElement('div'), { className: 'cartao aviso',\n    textContent: 'Arquivo-fonte sem o protocolo embutido: monte com node scripts/montar-miniapps.js.' }));\n  throw new Error('PROTOCOLO_ATB ausente');\n}\nconst antibiogramaDe = germes => germes.map(g => (AB && AB.germes.find(b => b.germe === g)) || { germe: g, culturas: 0, linhas: [] });\n\nfunction el(tag, attrs, ...filhos) {\n  const n = document.createElement(tag);\n  for (const [k, v] of Object.entries(attrs || {})) {\n    if (v === null || v === undefined) continue;\n    if (k.startsWith('on')) n.addEventListener(k.slice(2), v); else n.setAttribute(k, v);\n  }\n  const por = f => { if (f === null || f === undefined || f === false) return;\n    if (Array.isArray(f)) f.forEach(por); else n.append(f.nodeType ? f : document.createTextNode(f)); };\n  filhos.forEach(por);\n  return n;\n}\n\n/* ---- caso ---- */\n$('publico').textContent = PROTOCOLO_ATB.publico;\n$('medico').value = lerLocal(CHAVE_MEDICO) || '';\n$('medico').oninput = () => gravarLocal(CHAVE_MEDICO, $('medico').value.trim());\nfor (const s of PROTOCOLO_ATB.sindromes) $('sindrome').append(el('option', { value: s.id }, s.rotulo));\n\nconst controles = new Map();\nlet ultimaAnalise = null;\nfunction sindromeAtual() { return PROTOCOLO_ATB.sindromes.find(s => s.id === $('sindrome').value); }\n\nfunction desenharPerguntas() {\n  controles.clear();\n  $('resultado').classList.add('oculto');\n  ultimaAnalise = null;\n  const s = sindromeAtual();\n  if (!s) { $('perguntas').replaceChildren(); $('germes').textContent = ''; $('analisar').classList.add('oculto'); return; }\n  $('germes').textContent = 'Germes prováveis (protocolo): ' + s.germes.join(', ') + '.';\n  $('perguntas').replaceChildren(...s.perguntas.map(p => {\n    const controle = p.tipo === 'escolha'\n      ? el('select', {}, p.opcoes.map(([v, r]) => el('option', { value: v }, r)))\n      : el('select', {}, el('option', { value: '' }, 'não'), el('option', { value: 'S' }, 'sim'));\n    controles.set(p.id, { controle, tipo: p.tipo });\n    return el('div', {}, el('label', {}, p.rotulo), controle,\n      p.ajuda ? el('ul', { class: 'ajuda' }, p.ajuda.map(a => el('li', {}, a))) : null);\n  }));\n  $('analisar').classList.remove('oculto');\n}\n$('sindrome').onchange = desenharPerguntas;\n\nfunction tabelaAntibiograma(bloco) {\n  const linhas = bloco.linhas.slice(0, 12);\n  return el('details', {},\n    el('summary', {}, el('span', {}, bloco.germe), el('i', {}, bloco.culturas + ' isolados')),\n    linhas.length ? el('table', {},\n      el('thead', {}, el('tr', {}, el('th', {}, 'Antibiótico'), el('th', { class: 'n' }, '%R'), el('th', { class: 'n' }, 'n'))),\n      el('tbody', {}, linhas.map(l => {\n        const alta = l.testados >= 20 && l.pctR >= 30;\n        return el('tr', {}, el('td', {}, l.rotulo), el('td', { class: 'n' + (alta ? ' alta' : '') }, l.pctR + '%'), el('td', { class: 'n' }, String(l.testados)));\n      })))\n      : el('p', { class: 'suave', style: 'margin:0 0 10px' }, 'Sem antibiograma local para este germe no período.'));\n}\n\n$('analisar').onclick = () => {\n  const s = sindromeAtual();\n  if (!s) return;\n  const respostas = {}, legivel = [];\n  for (const p of s.perguntas) {\n    const { controle, tipo } = controles.get(p.id);\n    if (tipo === 'escolha') {\n      respostas[p.id] = controle.value;\n      legivel.push(p.rotulo + ': ' + controle.selectedOptions[0].textContent);\n    } else {\n      respostas[p.id] = controle.value === 'S';\n      legivel.push(p.rotulo + ': ' + (respostas[p.id] ? 'sim' : 'não'));\n    }\n  }\n  const decisao = s.decidir(respostas);\n  const antibiograma = antibiogramaDe(s.germes);\n  const avisosLocais = AB ? avisosDeResistenciaLocal(decisao.esquemas, antibiograma, AB.periodoTexto) : [];\n  const avisos = [...avisosLocais, ...decisao.avisos];\n  const renal = ajusteRenalDosEsquemas(decisao.esquemas);\n  ultimaAnalise = { sindrome: s.rotulo, respostas: legivel.join(' | '),\n    esquema: decisao.esquemas.map(e => e.rotulo + ' — ' + e.posologia).join(' | '), avisosLocais: avisosLocais.length };\n\n  const conduta = el('input', { type: 'text', id: 'conduta', placeholder: 'só se diferente da sugestão' });\n  /* Tudo passa por el(): replaceChildren não ignora null nem arrays (virava um \"null\" na tela). */\n  $('resultado').replaceChildren(el('div', {},\n    el('h2', {}, 'Sugestão — ' + s.rotulo),\n    el('div', {}, decisao.esquemas.map(e => el('div', { class: 'esq' }, el('div', { class: 'rot' }, e.rotulo), el('div', { class: 'pos' }, e.posologia)))),\n    avisos.length ? el('div', { class: 'cartao aviso', style: 'margin:10px 0 0' },\n      el('strong', {}, AB ? '⚠ Avisos dos dados locais' : '⚠ Avisos do protocolo'), el('ul', {}, avisos.map(a => el('li', {}, a)))) : null,\n    el('h3', {}, 'Culturas e exames antes do antibiótico'),\n    el('ul', { class: 'exames' }, decisao.exames.map(x => el('li', {}, x))),\n    el('h3', {}, 'Ajuste à função renal'),\n    el('p', { class: 'suave', style: 'margin:0 0 6px' }, ORIENTACAO_RENAL),\n    renal.length ? el('div', {}, renal.map(r => el('details', {},\n      el('summary', {}, el('span', {}, r.rotulo), el('i', {}, r.faixas.length + ' faixas')),\n      r.nota ? el('p', { class: 'suave', style: 'margin:0 0 6px' }, r.nota) : null,\n      el('table', {},\n        el('thead', {}, el('tr', {}, el('th', {}, 'TFG/ClCr (mL/min)'), el('th', {}, 'Dose'))),\n        el('tbody', {}, r.faixas.map(([tfg, dose]) => el('tr', {}, el('td', { class: 'n', style: 'text-align:left;white-space:nowrap' }, tfg), el('td', {}, dose))))))))\n      : el('p', { class: 'suave', style: 'margin:0' }, 'Nenhuma droga deste esquema precisa de ajuste renal.'),\n    AB ? [\n      el('h3', {}, 'Antibiograma local dos germes prováveis'),\n      el('p', { class: 'suave', style: 'margin:0 0 6px' }, `Culturas do hospital com antibiograma no banco da CCIH, ${AB.periodoTexto} (consolidado em ${AB.geradoEm}). `\n        + 'Linhas em vermelho: ≥30% de resistência com n ≥ 20.'),\n      el('div', {}, antibiograma.map(tabelaAntibiograma))] : null,\n    el('label', {}, 'Conduta adotada'), conduta,\n    el('button', { class: 'principal', onclick: registrar }, 'Registrar decisão'),\n    el('p', { class: 'suave', style: 'margin:10px 0 0' }, REVISAO_PROTOCOLO_ATB),\n    el('p', { class: 'suave' }, 'Fonte: ' + PROTOCOLO_ATB.fonte + '. Ferramenta de APOIO à decisão — não substitui o julgamento clínico nem a avaliação da CCIH para antimicrobianos auditados.'),\n    (PROTOCOLO_ATB.adendos || []).length ? el('p', { class: 'suave' }, 'Adendos validados pela CCIH: '\n      + PROTOCOLO_ATB.adendos.map(a => a.data.split('-').reverse().join('/') + ' — ' + a.texto).join(' · ')) : null));\n  $('resultado').classList.remove('oculto');\n  $('resultado').scrollIntoView({ behavior: 'smooth', block: 'start' });\n};\n\n/* ---- registros no aparelho ---- */\nlet registros = [];\ntry { registros = JSON.parse(lerLocal(CHAVE) || '[]'); } catch (e) { registros = []; }\nfunction gravar() { gravarLocal(CHAVE, JSON.stringify(registros)); conferirArmazenamento(); desenharLista(); }\n\nfunction registrar() {\n  if (!ultimaAnalise) return;\n  const agora = new Date();\n  registros.push({\n    Data: agora.toISOString().slice(0, 10), Hora: agora.toTimeString().slice(0, 5),\n    Prontuario: $('prontuario').value.trim(), Sindrome: ultimaAnalise.sindrome, Respostas: ultimaAnalise.respostas,\n    EsquemaSugerido: ultimaAnalise.esquema, AvisosLocais: String(ultimaAnalise.avisosLocais),\n    CondutaAdotada: ($('conduta') || {}).value || '', AntibiogramaPeriodo: AB ? AB.periodoTexto : '',\n    CriadoPor: $('medico').value.trim(), CriadoEm: agora.toISOString().slice(0, 16).replace('T', ' '), enviadoEm: null\n  });\n  gravar();\n  $('prontuario').value = '';\n  $('resultado').classList.add('oculto');\n  ultimaAnalise = null;\n  avisar('Decisão registrada. Envie à CCIH quando tiver rede.');\n  $('lista').scrollIntoView({ behavior: 'smooth', block: 'start' });\n}\n\nfunction desenharLista() {\n  const lista = $('lista');\n  lista.replaceChildren();\n  registros.forEach((r, i) => {\n    const div = el('div', { class: 'item' },\n      el('button', { class: 'excluir', style: 'float:right', onclick: () => { registros.splice(i, 1); gravar(); } }, 'excluir'),\n      el('div', {}, el('strong', {}, r.Sindrome), (r.Prontuario ? ' · pront. ' + r.Prontuario : '') + ' · ' + r.Data + ' ' + r.Hora),\n      el('div', { class: 'suave' }, r.EsquemaSugerido),\n      el('div', { class: 'selos' },\n        Number(r.AvisosLocais) ? el('span', {}, r.AvisosLocais + ' aviso(s) local(is)') : null,\n        r.CondutaAdotada ? el('span', {}, 'conduta: ' + r.CondutaAdotada) : null,\n        r.enviadoEm ? el('span', { class: 'enviado' }, 'enviado') : el('span', {}, 'aguardando envio')));\n    lista.appendChild(div);\n  });\n  const pendentes = registros.filter(r => !r.enviadoEm).length;\n  $('resumo').textContent = registros.length\n    ? `${registros.length} decisão(ões) registrada(s) neste aparelho · ${pendentes} aguardando envio`\n    : 'Nenhuma decisão registrada ainda.';\n}\n\n/* ---- envio (mesmo caminho dos outros miniapps: Apps Script → Drive; senão, arquivo + e-mail) ---- */\nfunction csvCampo(v) { v = String(v == null ? '' : v); return /[;\"\\n]/.test(v) ? '\"' + v.replace(/\"/g, '\"\"') + '\"' : v; }\nfunction tabelaCSV(nome, objetos) {\n  let saida = '##' + nome + '\\n';\n  if (!objetos.length) return saida;\n  const colunas = Object.keys(objetos[0]);\n  saida += colunas.join(';') + '\\n';\n  saida += objetos.map(o => colunas.map(c => csvCampo(o[c])).join(';')).join('\\n') + '\\n';\n  return saida;\n}\nfunction avisar(texto, erro) {\n  let st = document.getElementById('statusEnvio');\n  if (!st) { st = document.createElement('p'); st.id = 'statusEnvio'; $('enviar').after(st); }\n  st.style.cssText = 'font-weight:600;font-size:14px;margin-top:8px;color:' + (erro ? '#b03a2e' : '#0d3f7a');\n  st.textContent = texto;\n}\nasync function entregarArquivo(nome, texto) {\n  if (ENVIO_URL) {\n    try {\n      await fetch(ENVIO_URL, { method: 'POST', mode: 'no-cors', headers: { 'Content-Type': 'text/plain' },\n        body: JSON.stringify({ segredo: ENVIO_SEGREDO, nome: nome, conteudo: texto }) });\n      avisar('Enviado para a pasta da CCIH no Drive: ' + nome);\n      return true;\n    } catch (e) {\n      avisar('Sem conexão para o envio direto — salvando o arquivo para enviar por e-mail.', true);\n    }\n  }\n  try {\n    const blob = new Blob(['﻿' + texto], { type: 'text/csv;charset=utf-8' });\n    const url = URL.createObjectURL(blob);\n    const a = document.createElement('a');\n    a.href = url; a.download = nome;\n    document.body.appendChild(a); a.click(); a.remove();\n    setTimeout(() => URL.revokeObjectURL(url), 60000);\n    avisar('Arquivo \"' + nome + '\" salvo na pasta Downloads.');\n    const status = document.getElementById('statusEnvio');\n    const email = document.createElement('a');\n    email.href = 'mailto:' + EMAIL_DESTINO + '?subject=' + encodeURIComponent('CCIH — ' + nome)\n      + '&body=' + encodeURIComponent('Segue em anexo o arquivo ' + nome + ' (anexe-o pela pasta Downloads).');\n    email.textContent = '✉ Abrir e-mail para ' + EMAIL_DESTINO + ' (anexe o arquivo baixado)';\n    email.style.cssText = 'display:block;margin-top:8px;padding:10px;border:1px solid #0d3f7a;border-radius:8px;color:#0d3f7a;font-weight:700;text-align:center;text-decoration:none';\n    status.appendChild(email);\n    return true;\n  } catch (e) {\n    avisar('Não foi possível exportar: ' + e.message, true);\n    return false;\n  }\n}\n\n$('enviar').onclick = async () => {\n  const pendentes = registros.filter(r => !r.enviadoEm);\n  if (!pendentes.length) { avisar('Nada aguardando envio.', true); return; }\n  const quem = ($('medico').value.trim() || 'medico').replace(/[^A-Za-z0-9]+/g, '-');\n  const hoje = new Date().toISOString().slice(0, 10);\n  const nome = `DECISAO-ATB_${quem}_${hoje}_${Date.now().toString(36)}.csv`;\n  const linhas = pendentes.map(({ enviadoEm, ...r }) => r);\n  const pacote = '##ccih-miniapp;tipo=decisao_atb;versao=1\\n' + tabelaCSV('decisoes', linhas);\n  if (await entregarArquivo(nome, pacote)) {\n    pendentes.forEach(r => r.enviadoEm = Date.now());\n    gravar();\n  }\n};\n$('limpar').onclick = () => {\n  if (!registros.length) return;\n  if (confirm('Apagar todas as decisões registradas neste aparelho? Se ainda não foram enviadas, serão perdidas.')) { registros = []; gravar(); }\n};\n\n$('rodape').textContent = AB\n  ? `Antibiograma consolidado ${AB.periodoTexto}, gerado em ${AB.geradoEm}. Para atualizar, a CCIH reconstrói o miniapp e o mesmo link passa a servir a versão nova.`\n  : 'Versão inicial: recomendações do protocolo institucional (consenso). O antibiograma do hospital entra numa versão futura, quando o banco tiver painel suficiente.';\ndesenharLista();\nconferirArmazenamento();\n</script>\n</body>\n</html>\n","higiene-maos.html":"<!DOCTYPE html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>CCIH — Higiene das mãos</title>\n<style>\n* { box-sizing: border-box; } body { font-family: system-ui, sans-serif; margin: 0; background: #f2f4f7; color: #1f2933; }\nheader { background: #0d3f7a; color: #fff; padding: 14px 16px; font-size: 18px; font-weight: 700; }\nmain { padding: 12px; max-width: 560px; margin: 0 auto; }\n.cartao { background: #fff; border: 1px solid #dde3ea; border-radius: 10px; padding: 12px; margin-bottom: 12px; }\nlabel { display: block; font-size: 13px; color: #61707f; margin-top: 8px; }\ninput, select { width: 100%; font-size: 16px; padding: 9px; border: 1px solid #c3ccd6; border-radius: 8px; background: #fff; }\n.linha { display: flex; gap: 8px; } .linha > div { flex: 1; }\nbutton { font-size: 16px; font-weight: 700; border-radius: 10px; padding: 16px 8px; border: none; cursor: pointer; width: 100%; }\n.acoes { display: flex; gap: 8px; margin-top: 10px; }\n.alcool { background: #0d3f7a; color: #fff; } .agua { background: #185fa5; color: #fff; } .nao { background: #a32d2d; color: #fff; }\nbutton:disabled { opacity: .35; }\n.cronometro { text-align: center; margin-top: 10px; display: none; }\n.cronometro .tempo { font-size: 44px; font-weight: 700; color: #0d3f7a; font-variant-numeric: tabular-nums; }\n.concluir { background: #e5b95c; color: #412402; margin-top: 8px; }\n.numeros { display: flex; gap: 8px; text-align: center; margin-top: 10px; }\n.numeros div { flex: 1; background: #f2f4f7; border-radius: 8px; padding: 8px; }\n.numeros strong { font-size: 20px; display: block; }\n.suave { color: #61707f; font-size: 13px; }\n.secundario { background: #fff; color: #0d3f7a; border: 1px solid #0d3f7a; margin-top: 10px; font-weight: 600; }\n.desfazer { background: #fdf3dd; color: #633806; border: 1px solid #e5b95c; margin-top: 8px; font-weight: 600; }\n.excluir { background: none; border: none; color: #b03a2e; font-size: 14px; margin-top: 6px; }\n.aviso { border-left: 5px solid #e5b95c; background: #fdf3dd; color: #633806; }\n.aviso p { margin: 6px 0 0; font-size: 14px; }\n.versao { font-size: 12px; font-weight: 400; opacity: .7; }\n</style>\n</head>\n<body>\n<header>Auditoria de higiene das mãos <span class=\"versao\">v01.09</span></header>\n<main>\n  <div class=\"cartao aviso\" id=\"avisoAbertura\">\n    <strong>Este arquivo precisa ser aberto no navegador.</strong>\n    <p>Você está vendo apenas a pré-visualização do arquivo, que não executa o aplicativo.\n       Toque nos três pontinhos (⋮) no canto da tela e escolha <strong>Abrir com → Chrome</strong>,\n       ou baixe o arquivo e abra-o pela pasta Downloads.</p>\n  </div>\n  <div class=\"cartao aviso\" id=\"avisoArmazenamento\" style=\"display:none\">\n    <strong>Os registros não estão sendo salvos neste aparelho.</strong>\n    <p>Se fechar a página, perde o que digitou. Baixe o arquivo e abra-o pelo navegador.</p>\n  </div>\n  <div class=\"cartao\">\n    <div class=\"linha\">\n      <div><label>Setor</label><select id=\"setor\"></select><input type=\"text\" id=\"setorOutro\" placeholder=\"digite o setor\" style=\"display:none;margin-top:4px\"></div>\n      <div><label>Observador</label><input type=\"text\" id=\"observador\" placeholder=\"seu nome\"></div>\n    </div>\n    <div class=\"linha\">\n      <div><label>Tipo de higienização</label>\n        <select id=\"tipo\"><option>Simples</option><option>Cirúrgica</option></select></div>\n      <div><label>Categoria profissional</label>\n        <select id=\"categoria\">\n          <option>Médico</option><option>Enfermeiro</option><option>Técnico de enfermagem</option>\n          <option>Fisioterapeuta</option><option>Outro</option>\n        </select></div>\n    </div>\n    <div id=\"linhaMomento\">\n      <label>Momento (OMS)</label>\n      <select id=\"momento\">\n        <option value=\"1\">1 — Antes de tocar o paciente</option>\n        <option value=\"2\">2 — Antes de procedimento asséptico</option>\n        <option value=\"3\">3 — Após risco de exposição a fluidos</option>\n        <option value=\"4\">4 — Após tocar o paciente</option>\n        <option value=\"5\">5 — Após tocar áreas próximas</option>\n      </select>\n    </div>\n  </div>\n  <div class=\"cartao\">\n    <p class=\"suave\" style=\"margin:0 0 4px\">Ao iniciar a higienização, toque no produto — o cronômetro dispara. Toque em concluir quando terminar.</p>\n    <div class=\"acoes\">\n      <button class=\"alcool\" data-acao=\"Álcool\">Álcool</button>\n      <button class=\"agua\" data-acao=\"Água e sabão\">Água e sabão</button>\n      <button class=\"nao\" data-acao=\"Não higienizou\">Não higienizou</button>\n    </div>\n    <div class=\"cronometro\" id=\"cronometro\">\n      <div class=\"tempo\" id=\"tempo\">0 s</div>\n      <div class=\"suave\" id=\"acaoAtual\"></div>\n      <button class=\"concluir\" id=\"concluir\">Concluir higienização e registrar</button>\n    </div>\n    <div class=\"numeros\">\n      <div><strong id=\"nTotal\">0</strong><span class=\"suave\">oportunidades</span></div>\n      <div><strong id=\"nAdesao\">—</strong><span class=\"suave\">adesão</span></div>\n      <div><strong id=\"nTempo\">—</strong><span class=\"suave\">tempo médio</span></div>\n    </div>\n    <button class=\"desfazer\" id=\"desfazer\">Desfazer último registro</button>\n  </div>\n  <div class=\"cartao\">\n    <button class=\"secundario\" id=\"exportar\">Exportar e enviar planilha</button>\n    <button class=\"excluir\" id=\"limpar\" style=\"width:100%\">Apagar registros do aparelho</button>\n  </div>\n</main>\n<script>\nconst SETORES = [];  /* o montador injeta aqui os setores do hospital */\n\n/* Setor vem da lista do hospital (injetada pelo montador a partir do config.xlsx).\n   Sem lista (fonte cru, sem montar), o campo vira texto livre como antes. \"Outro\" cobre\n   setor novo que ainda não entrou no vocabulário. */\nconst OUTRO_SETOR = '__outro__';\nfunction montarSeletorSetor() {\n  const sel = $('setor');\n  if (!SETORES.length) {\n    const texto = document.createElement('input');\n    texto.type = 'text'; texto.id = 'setor'; texto.placeholder = 'setor';\n    sel.replaceWith(texto);\n    return;\n  }\n  sel.append(new Option('— escolha o setor —', ''));\n  SETORES.forEach(s => sel.append(new Option(s, s)));\n  sel.append(new Option('Outro (digitar)', OUTRO_SETOR));\n  sel.addEventListener('change', () => {\n    $('setorOutro').style.display = sel.value === OUTRO_SETOR ? '' : 'none';\n  });\n}\nfunction setorAtual() {\n  const el = $('setor');\n  if (el.tagName === 'INPUT') return el.value.trim();\n  return el.value === OUTRO_SETOR ? $('setorOutro').value.trim() : el.value;\n}\nfunction restaurarSetor(salvo) {\n  const el = $('setor');\n  if (!salvo) return;\n  if (el.tagName === 'INPUT') { el.value = salvo; return; }\n  if (SETORES.includes(salvo)) el.value = salvo;\n  else { el.value = OUTRO_SETOR; $('setorOutro').value = salvo; $('setorOutro').style.display = ''; }\n}\n\nconst CHAVE = 'ccih.higiene.v2';\nconst EMAIL_DESTINO = 'defina-o-email-da-ccih@exemplo.br';\nconst ENVIO_URL = '';\nconst ENVIO_SEGREDO = 'troque-este-segredo';\nconst $ = id => document.getElementById(id);\n\n/* O aviso de abertura fica visível por padrão e some assim que o script roda: se a página\n   for aberta num visualizador que não executa JavaScript (a pré-visualização do Google\n   Drive, por exemplo), o usuário lê o que fazer em vez de encontrar um formulário morto. */\n$('avisoAbertura').style.display = 'none';\n\n/* Esses mesmos visualizadores rodam a página numa caixa sem armazenamento, e aí tocar em\n   localStorage lança exceção. Sem esta proteção o miniapp morria na primeira linha. */\nlet armazenamentoOk = true;\nconst guardadoNaMemoria = {};\nfunction lerLocal(chave) {\n  try { return localStorage.getItem(chave); }\n  catch (e) { armazenamentoOk = false; return chave in guardadoNaMemoria ? guardadoNaMemoria[chave] : null; }\n}\nfunction gravarLocal(chave, valor) {\n  try { localStorage.setItem(chave, valor); }\n  catch (e) { armazenamentoOk = false; guardadoNaMemoria[chave] = valor; }\n}\nfunction conferirArmazenamento() {\n  $('avisoArmazenamento').style.display = armazenamentoOk ? 'none' : '';\n}\nmontarSeletorSetor();\nrestaurarSetor(lerLocal(CHAVE + '.setor') || '');\n$('observador').value = lerLocal(CHAVE + '.observador') || '';\n$('tipo').value = lerLocal(CHAVE + '.tipo') || 'Simples';\nlet registros = JSON.parse(lerLocal(CHAVE) || '[]');\nlet cronometro = null;\n\n$('tipo').addEventListener('change', () => {\n  $('linhaMomento').style.display = $('tipo').value === 'Cirúrgica' ? 'none' : '';\n});\n$('tipo').dispatchEvent(new Event('change'));\n\nfunction gravar() { gravarLocal(CHAVE, JSON.stringify(registros)); conferirArmazenamento(); desenhar(); }\nfunction desenhar() {\n  const total = registros.length;\n  const nao = registros.filter(r => r.Acao === 'Não higienizou').length;\n  const tempos = registros.map(r => Number(r.DuracaoSegundos)).filter(t => t > 0);\n  $('nTotal').textContent = total;\n  $('nAdesao').textContent = total ? Math.round((total - nao) / total * 100) + '%' : '—';\n  $('nTempo').textContent = tempos.length ? Math.round(tempos.reduce((a, b) => a + b, 0) / tempos.length) + ' s' : '—';\n}\n\nfunction registrar(acao, duracao) {\n  registros.push({\n    ID_Observacao: Date.now() + '-' + Math.floor(Math.random() * 10000),\n    Data: new Date().toISOString().slice(0, 10),\n    Setor: setorAtual(), Observador: $('observador').value.trim(),\n    TipoHigienizacao: $('tipo').value, Categoria: $('categoria').value,\n    Momento: $('tipo').value === 'Cirúrgica' ? '' : $('momento').value,\n    Acao: acao, DuracaoSegundos: duracao ? String(duracao) : '',\n    CriadoEm: new Date().toISOString()\n  });\n  gravar();\n}\n\nfunction alternarBotoes(desabilitar) {\n  document.querySelectorAll('.acoes button').forEach(b => b.disabled = desabilitar);\n}\n\ndocument.querySelectorAll('.acoes button').forEach(botao => {\n  botao.onclick = () => {\n    if (!setorAtual() || !$('observador').value.trim()) { alert('Preencha setor e observador.'); return; }\n    gravarLocal(CHAVE + '.setor', setorAtual());\n    gravarLocal(CHAVE + '.observador', $('observador').value.trim());\n    gravarLocal(CHAVE + '.tipo', $('tipo').value);\n    const acao = botao.dataset.acao;\n    if (acao === 'Não higienizou') { registrar(acao, 0); return; }\n    cronometro = { acao, inicio: Date.now() };\n    $('acaoAtual').textContent = acao + ' — higienização em andamento';\n    $('tempo').textContent = '0 s';\n    $('cronometro').style.display = 'block';\n    alternarBotoes(true);\n    cronometro.intervalo = setInterval(() => {\n      $('tempo').textContent = Math.round((Date.now() - cronometro.inicio) / 1000) + ' s';\n    }, 250);\n  };\n});\n\n$('concluir').onclick = () => {\n  if (!cronometro) return;\n  clearInterval(cronometro.intervalo);\n  const duracao = Math.max(1, Math.round((Date.now() - cronometro.inicio) / 1000));\n  registrar(cronometro.acao, duracao);\n  cronometro = null;\n  $('cronometro').style.display = 'none';\n  alternarBotoes(false);\n};\n\n$('desfazer').onclick = () => { registros.pop(); gravar(); };\n\nfunction csvCampo(v) { v = String(v == null ? '' : v); return /[;\"\\n]/.test(v) ? '\"' + v.replace(/\"/g, '\"\"') + '\"' : v; }\nfunction tabelaCSV(nome, objetos) {\n  let saida = '##' + nome + '\\n';\n  if (!objetos.length) return saida;\n  const colunas = Object.keys(objetos[0]);\n  saida += colunas.join(';') + '\\n';\n  saida += objetos.map(o => colunas.map(c => csvCampo(o[c])).join(';')).join('\\n') + '\\n';\n  return saida;\n}\nfunction avisar(texto, erro) {\n  let el = document.getElementById('statusExporte');\n  if (!el) {\n    el = document.createElement('p');\n    el.id = 'statusExporte';\n    document.getElementById('exportar').after(el);\n  }\n  el.style.cssText = 'font-weight:600;font-size:14px;margin-top:8px;color:' + (erro ? '#b03a2e' : '#0d3f7a');\n  el.textContent = texto;\n}\nasync function entregarArquivo(nome, texto) {\n  if (ENVIO_URL) {\n    try {\n      await fetch(ENVIO_URL, { method: 'POST', mode: 'no-cors', headers: { 'Content-Type': 'text/plain' },\n        body: JSON.stringify({ segredo: ENVIO_SEGREDO, nome: nome, conteudo: texto }) });\n      avisar('Enviado para a pasta da CCIH no Drive: ' + nome);\n      return true;\n    } catch (e) {\n      avisar('Sem conexão para o envio direto — salvando o arquivo para enviar por e-mail.', true);\n    }\n  }\n  try {\n    /* Blob + createObjectURL, e não data: URI: o celular bloqueia o download de data:\n       quando o arquivo passa de alguns KB, e a exportação falhava calada. */\n    const blob = new Blob(['﻿' + texto], { type: 'text/csv;charset=utf-8' });\n    const url = URL.createObjectURL(blob);\n    const a = document.createElement('a');\n    a.href = url;\n    a.download = nome;\n    document.body.appendChild(a); a.click(); a.remove();\n    setTimeout(() => URL.revokeObjectURL(url), 60000);\n    avisar('Arquivo \"' + nome + '\" salvo na pasta Downloads.');\n    /* O e-mail fica num botão para o usuário tocar: disparar duas navegações seguidas\n       (download + mailto) faz o celular cancelar uma das duas. */\n    const status = document.getElementById('statusExporte');\n    const email = document.createElement('a');\n    email.href = 'mailto:' + EMAIL_DESTINO + '?subject=' + encodeURIComponent('CCIH — ' + nome)\n      + '&body=' + encodeURIComponent('Segue em anexo o arquivo ' + nome + ' (anexe-o pela pasta Downloads).');\n    email.textContent = '✉ Abrir e-mail para ' + EMAIL_DESTINO + ' (anexe o arquivo baixado)';\n    email.style.cssText = 'display:block;margin-top:8px;padding:10px;border:1px solid #0d3f7a;border-radius:8px;'\n      + 'color:#0d3f7a;font-weight:700;text-align:center;text-decoration:none';\n    status.appendChild(email);\n    const baixar = document.createElement('a');\n    baixar.href = url;\n    baixar.download = nome;\n    baixar.textContent = '↓ Baixar de novo';\n    baixar.style.cssText = 'display:block;margin-top:6px;color:#61707f;font-size:13px;text-align:center';\n    status.appendChild(baixar);\n    return true;\n  } catch (e) {\n    avisar('Não foi possível exportar: ' + e.message, true);\n    return false;\n  }\n}\n$('exportar').onclick = async () => {\n  if (!registros.length) { avisar('Nenhum registro para exportar.', true); return; }\n  const setor = (setorAtual() || 'setor').replace(/[^A-Za-z0-9]+/g, '-');\n  const nome = `HM_${setor}_${new Date().toISOString().slice(0, 10)}.csv`;\n  const texto = '##ccih-miniapp;tipo=higiene_maos;versao=3\\n' + tabelaCSV('observacoes', registros);\n  await entregarArquivo(nome, texto);\n};\n$('limpar').onclick = () => { if (confirm('Apagar todos os registros deste aparelho?')) { registros = []; gravar(); } };\ndesenhar();\n</script>\n</body>\n</html>\n","visita-uti.html":"<!DOCTYPE html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>CCIH — Visita à UTI</title>\n<style>\n* { box-sizing: border-box; } body { font-family: system-ui, sans-serif; margin: 0; background: #f2f4f7; color: #1f2933; }\nheader { background: #0d3f7a; color: #fff; padding: 14px 16px; font-size: 18px; font-weight: 700; }\nmain { padding: 12px; max-width: 560px; margin: 0 auto; }\n.cartao { background: #fff; border: 1px solid #dde3ea; border-radius: 10px; padding: 12px; margin-bottom: 12px; }\nlabel { display: block; font-size: 13px; color: #61707f; margin-top: 8px; }\ninput[type=text], input[type=password], input[type=date], select { width: 100%; font-size: 16px; padding: 9px; border: 1px solid #c3ccd6; border-radius: 8px; background: #fff; }\n.linha { display: flex; gap: 8px; } .linha > div { flex: 1; }\n.chk { display: flex; align-items: center; gap: 8px; margin-top: 10px; font-weight: 600; }\n.chk input { width: 22px; height: 22px; }\n.bloco { border-left: 3px solid #d0e0f5; padding-left: 10px; margin: 6px 0 6px 6px; }\n.itemlista { display: flex; gap: 6px; align-items: center; margin-top: 6px; }\n.itemlista select { flex: 1; }\nbutton { font-size: 15px; font-weight: 600; border-radius: 8px; padding: 11px; border: none; cursor: pointer; width: 100%; margin-top: 8px; }\n.principal { background: #0d3f7a; color: #fff; } .secundario { background: #fff; color: #0d3f7a; border: 1px solid #0d3f7a; }\n.mini { width: auto; padding: 6px 10px; font-size: 13px; margin: 6px 0 0; background: #e7effb; color: #0d3f7a; }\n.remover { width: auto; background: none; color: #b03a2e; font-size: 18px; padding: 4px 8px; margin: 0; }\n.item { border-bottom: 1px solid #eef1f5; padding: 10px 0; font-size: 14px; cursor: pointer; }\n.item:active { background: #f2f7fd; }\n.selos span { background: #e7effb; color: #0d3f7a; border-radius: 10px; padding: 2px 8px; font-size: 12px; margin-right: 4px; }\n.selos .enviado { background: #fdf3dd; color: #633806; }\n.excluir { background: none; border: none; color: #b03a2e; font-size: 13px; width: auto; padding: 2px 6px; margin: 0; float: right; }\n.suave { color: #61707f; font-size: 13px; }\n.oculto { display: none; }\n.aviso { border-left: 5px solid #e5b95c; background: #fdf3dd; color: #633806; }\n.aviso p { margin: 6px 0 0; font-size: 14px; }\n.versao { font-size: 12px; font-weight: 400; opacity: .7; }\n</style>\n</head>\n<body>\n<header>Visita da CCIH à UTI <span class=\"versao\">v01.10</span></header>\n<main>\n  <div class=\"cartao aviso\" id=\"avisoAbertura\">\n    <strong>Este arquivo precisa ser aberto no navegador.</strong>\n    <p>Você está vendo apenas a pré-visualização do arquivo, que não executa o aplicativo.\n       Toque nos três pontinhos (⋮) no canto da tela e escolha <strong>Abrir com → Chrome</strong>,\n       ou baixe o arquivo e abra-o pela pasta Downloads.</p>\n  </div>\n  <div class=\"cartao aviso\" id=\"avisoArmazenamento\" style=\"display:none\">\n    <strong>Os registros não estão sendo salvos neste aparelho.</strong>\n    <p>Se fechar a página, perde o que digitou. Baixe o arquivo e abra-o pelo navegador.</p>\n  </div>\n  <!-- Lista dos leitos de hoje (só na versão gerada pelo aplicativo, cifrada com senha). -->\n  <div class=\"cartao oculto\" id=\"telaSenha\">\n    <strong>Lista dos leitos de hoje — protegida.</strong>\n    <p class=\"suave\" id=\"infoLista\"></p>\n    <label>Senha fornecida pela CCIH</label><input type=\"password\" id=\"senha\" autocomplete=\"off\">\n    <button class=\"principal\" id=\"abrirLista\">Abrir lista de pacientes</button>\n    <p class=\"suave\" id=\"erroSenha\"></p>\n  </div>\n  <div class=\"cartao oculto\" id=\"cartaoLista\">\n    <strong>Pacientes do setor hoje</strong> <span class=\"suave\" id=\"resumoLista\"></span>\n    <p class=\"suave\">Toque em <b>avaliar</b> para preencher leito e prontuário sem digitar. Sinais vitais vêm do texto das evoluções — confirme no leito.</p>\n    <div id=\"listaPacientes\"></div>\n  </div>\n  <div class=\"cartao\">\n    <div class=\"linha\">\n      <div><label>Data</label><input type=\"date\" id=\"data\"></div>\n      <div><label>Setor</label><select id=\"setor\"></select><input type=\"text\" id=\"setorOutro\" placeholder=\"digite o setor\" style=\"display:none;margin-top:4px\"></div>\n    </div>\n    <label>Quem está visitando</label><input type=\"text\" id=\"observador\" placeholder=\"seu nome\">\n  </div>\n\n  <div class=\"cartao\" id=\"formPaciente\">\n    <div class=\"linha\">\n      <div><label>Leito</label><input type=\"text\" id=\"leito\"></div>\n      <div><label>Prontuário</label><input type=\"text\" id=\"prontuario\" inputmode=\"numeric\"></div>\n    </div>\n\n    <div class=\"chk\"><input type=\"checkbox\" id=\"temCvc\"><span>Cateter venoso central</span></div>\n    <div class=\"bloco oculto\" id=\"blocoCvc\">\n      <div id=\"listaCateteres\"></div>\n      <button class=\"mini\" id=\"maisCateter\">+ outro cateter central</button>\n    </div>\n\n    <div class=\"chk\"><input type=\"checkbox\" id=\"temVm\"><span>Ventilação mecânica</span></div>\n    <div class=\"bloco oculto\" id=\"blocoVm\"><label>Indicação</label><select id=\"vmInd\"></select>\n      <label style=\"display:flex;align-items:center;gap:6px;margin-top:6px\"><input type=\"checkbox\" id=\"vmRetirar\" style=\"width:18px;height:18px\"> sugerir retirada</label></div>\n\n    <div class=\"chk\"><input type=\"checkbox\" id=\"temSvd\"><span>Sonda vesical de demora</span></div>\n    <div class=\"bloco oculto\" id=\"blocoSvd\"><label>Indicação</label><select id=\"svdInd\"></select>\n      <label style=\"display:flex;align-items:center;gap:6px;margin-top:6px\"><input type=\"checkbox\" id=\"svdRetirar\" style=\"width:18px;height:18px\"> sugerir retirada</label></div>\n\n    <div class=\"chk\"><input type=\"checkbox\" id=\"temNpt\"><span>Nutrição parenteral</span></div>\n\n    <div class=\"chk\"><input type=\"checkbox\" id=\"temAtb\"><span>Avaliar antimicrobiano</span></div>\n    <div class=\"bloco oculto\" id=\"blocoAtb\">\n      <div id=\"listaAtbs\"></div>\n      <button class=\"mini\" id=\"maisAtb\">+ avaliar novo antimicrobiano</button>\n    </div>\n\n    <div class=\"chk\"><input type=\"checkbox\" id=\"suspeita\"><span>Suspeita de IRAS</span></div>\n    <div class=\"bloco oculto\" id=\"blocoFoco\"><label>Foco suspeito</label><select id=\"foco\"></select></div>\n    <label>Observações</label><input type=\"text\" id=\"obs\">\n    <button class=\"principal\" id=\"salvar\">Salvar paciente</button>\n    <button class=\"secundario oculto\" id=\"cancelar\">Cancelar edição</button>\n  </div>\n\n  <div class=\"cartao\">\n    <div id=\"lista\"></div>\n    <p class=\"suave\" id=\"resumo\"></p>\n    <button class=\"secundario\" id=\"exportar\">Exportar planilha do dia</button>\n    <p class=\"suave\">Após exportar, os registros continuam editáveis por 24 h — reexporte e reimporte no aplicativo que os dados são substituídos.</p>\n    <button class=\"excluir\" id=\"limpar\" style=\"width:100%\">Apagar todos os registros do aparelho</button>\n  </div>\n</main>\n<!--LISTA-CIFRADA-->\n<script>\nconst CHAVE = 'ccih.visita.uti.v2';\nconst EMAIL_DESTINO = 'defina-o-email-da-ccih@exemplo.br';\nconst ENVIO_URL = '';\nconst ENVIO_SEGREDO = 'troque-este-segredo';\nconst $ = id => document.getElementById(id);\n\n/* O aviso de abertura fica visível por padrão e some assim que o script roda: se a página\n   for aberta num visualizador que não executa JavaScript (a pré-visualização do Google\n   Drive, por exemplo), o usuário lê o que fazer em vez de encontrar um formulário morto. */\n$('avisoAbertura').style.display = 'none';\n\n/* Esses mesmos visualizadores rodam a página numa caixa sem armazenamento, e aí tocar em\n   localStorage lança exceção. Sem esta proteção o miniapp morria na primeira linha. */\nlet armazenamentoOk = true;\nconst guardadoNaMemoria = {};\nfunction lerLocal(chave) {\n  try { return localStorage.getItem(chave); }\n  catch (e) { armazenamentoOk = false; return chave in guardadoNaMemoria ? guardadoNaMemoria[chave] : null; }\n}\nfunction gravarLocal(chave, valor) {\n  try { localStorage.setItem(chave, valor); }\n  catch (e) { armazenamentoOk = false; guardadoNaMemoria[chave] = valor; }\n}\nfunction conferirArmazenamento() {\n  $('avisoArmazenamento').style.display = armazenamentoOk ? 'none' : '';\n}\n\nconst IND_CVC =['Drogas vasoativas', 'Monitorização hemodinâmica', 'Antibioticoterapia prolongada', 'Nutrição parenteral', 'Acesso venoso difícil', 'Hemodiálise', 'Quimioterapia', 'Outros'];\nconst IND_VM = ['Insuficiência respiratória', 'Proteção de via aérea / rebaixamento', 'Pós-operatório', 'Desmame em curso', 'Outros'];\nconst IND_SVD = ['Débito urinário rigoroso', 'Retenção urinária', 'Lesão sacral/perineal', 'Pós-operatório', 'Sedação profunda / bloqueio', 'Outros'];\nconst IND_ATB = ['Pneumonia', 'ITU', 'Infecção de pele e partes moles', 'Infecção abdominal', 'Corrente sanguínea / sepse', 'Sítio cirúrgico', 'Meningite / SNC', 'Profilaxia', 'Outros'];\nconst FOCOS = ['Pulmonar / PAV', 'Urinário', 'Corrente sanguínea / cateter', 'Sítio cirúrgico', 'Pele e partes moles', 'Abdominal', 'SNC', 'Sem foco definido', 'Outros'];\nconst AVALIACOES = ['Correto', 'Parcialmente correto', 'Incorreto'];\nconst RECOMENDACOES = ['Manter', 'Suspender', 'Modificar', 'Ajustar dose'];\n/* Lista fechada, igual ao vocabulário do aplicativo: digitado à mão, o mesmo antibiótico\n   viraria \"Tazocin\", \"pipe-tazo\" e \"Piperacilina+Tazobactam\" no banco. Quem não estiver\n   na lista entra por \"Outro\", que é raro e cai na revisão do vocabulário na importação. */\nconst SETORES = [];  /* o montador injeta aqui os setores do hospital */\n\n/* Setor vem da lista do hospital (injetada pelo montador a partir do config.xlsx).\n   Sem lista (fonte cru, sem montar), o campo vira texto livre como antes. \"Outro\" cobre\n   setor novo que ainda não entrou no vocabulário. */\nconst OUTRO_SETOR = '__outro__';\nfunction montarSeletorSetor() {\n  const sel = $('setor');\n  if (!SETORES.length) {\n    const texto = document.createElement('input');\n    texto.type = 'text'; texto.id = 'setor'; texto.placeholder = 'setor';\n    sel.replaceWith(texto);\n    return;\n  }\n  sel.append(new Option('— escolha o setor —', ''));\n  SETORES.forEach(s => sel.append(new Option(s, s)));\n  sel.append(new Option('Outro (digitar)', OUTRO_SETOR));\n  sel.addEventListener('change', () => {\n    $('setorOutro').style.display = sel.value === OUTRO_SETOR ? '' : 'none';\n  });\n}\nfunction setorAtual() {\n  const el = $('setor');\n  if (el.tagName === 'INPUT') return el.value.trim();\n  return el.value === OUTRO_SETOR ? $('setorOutro').value.trim() : el.value;\n}\nfunction restaurarSetor(salvo) {\n  const el = $('setor');\n  if (!salvo) return;\n  if (el.tagName === 'INPUT') { el.value = salvo; return; }\n  if (SETORES.includes(salvo)) el.value = salvo;\n  else { el.value = OUTRO_SETOR; $('setorOutro').value = salvo; $('setorOutro').style.display = ''; }\n}\n\nconst OUTRO_ATB = 'Outro (digitar)';\nconst ATBS = ['Amicacina', 'Amoxicilina', 'Amoxicilina + Ácido Clavulânico', 'Ampicilina',\n  'Ampicilina-sulbactam', 'Azitromicina', 'Aztreonam', 'Cefalotina', 'Cefazolina', 'Cefepima',\n  'Cefoxitina', 'Ceftazidima', 'Ceftazidima-avibactam', 'Ceftriaxona', 'Cefuroxima',\n  'Ciprofloxacino', 'Clindamicina', 'Colistina', 'Daptomicina', 'Eritromicina', 'Ertapenem',\n  'Gentamicina', 'Imipenem', 'Levofloxacino', 'Linezolida', 'Meropenem', 'Metronidazol',\n  'Nitrofurantoína', 'Norfloxacino', 'Oxacilina', 'Penicilina', 'Piperacilina-tazobactam',\n  'Polimixina B', 'Rifampicina', 'Sulfametoxazol-trimetoprima', 'Teicoplanina', 'Tigeciclina',\n  'Vancomicina',\n  /* Antifúngicos: a avaliação da UTI também os cobre (na primeira visita real já\n     apareceu fluconazol para suspeita de candidíase invasiva). */\n  'Anfotericina B lipossomal', 'Anidulafungina', 'Caspofungina', 'Fluconazol', 'Micafungina',\n  'Voriconazol',\n  /* Antivirais de uso comum na UTI. */\n  'Aciclovir', 'Oseltamivir'];\nATBS.sort((a, b) => a.localeCompare(b, 'pt'));\n\nfunction encherSelect(sel, opcoes, valor) {\n  sel.innerHTML = opcoes.map(o => `<option${o === valor ? ' selected' : ''}>${o}</option>`).join('');\n}\nencherSelect($('vmInd'), IND_VM);\nencherSelect($('svdInd'), IND_SVD);\nencherSelect($('foco'), FOCOS);\n\n$('data').value = new Date().toISOString().slice(0, 10);\nmontarSeletorSetor();\nrestaurarSetor(lerLocal(CHAVE + '.setor') || '');\n$('observador').value = lerLocal(CHAVE + '.observador') || '';\nlet registros = JSON.parse(lerLocal(CHAVE) || '[]');\nregistros = registros.filter(r => !r.exportadoEm || Date.now() - r.exportadoEm < 24 * 3600 * 1000);\nregistros.forEach(r => { r.cateteres = (r.cateteres || []).map(c => typeof c === 'string' ? { ind: c, retirar: false } : c); });\n$('suspeita').addEventListener('change', () => $('blocoFoco').classList.toggle('oculto', !$('suspeita').checked));\nlet editando = -1;\n\n['temCvc', 'temVm', 'temSvd', 'temAtb'].forEach(id => {\n  $(id).addEventListener('change', () => {\n    $('bloco' + id.slice(3)).classList.toggle('oculto', !$(id).checked);\n    if (id === 'temCvc' && $(id).checked && !$('listaCateteres').children.length) adicionarCateter();\n    if (id === 'temAtb' && $(id).checked && !$('listaAtbs').children.length) adicionarAtb();\n  });\n});\n\nfunction adicionarCateter(valor, retirar) {\n  const div = document.createElement('div');\n  div.className = 'itemlista';\n  const sel = document.createElement('select');\n  encherSelect(sel, IND_CVC, valor && valor.ind !== undefined ? valor.ind : valor);\n  const ret = document.createElement('label');\n  ret.style.cssText = 'display:flex;align-items:center;gap:4px;font-size:12px;color:#61707f';\n  ret.innerHTML = '<input type=\"checkbox\" style=\"width:18px;height:18px\"' + (retirar ? ' checked' : '') + '> retirar';\n  const rem = document.createElement('button');\n  rem.className = 'remover'; rem.textContent = '×';\n  rem.onclick = () => div.remove();\n  div.append(sel, ret, rem);\n  $('listaCateteres').appendChild(div);\n}\n$('maisCateter').onclick = () => adicionarCateter();\n\nfunction adicionarAtb(dados) {\n  dados = dados || {};\n  const div = document.createElement('div');\n  div.className = 'bloco';\n  div.innerHTML = '<label>Antimicrobiano em uso</label><select class=\"atbNome\"></select>'\n    + '<input type=\"text\" class=\"atbOutro\" placeholder=\"qual antibiótico?\" style=\"display:none;margin-top:6px\">'\n    + '<label>Indicação</label><select class=\"atbInd\"></select>'\n    + '<label>Avaliação</label><select class=\"atbAval\"></select>'\n    + '<label>Recomendação da CCIH</label><select class=\"atbRec\"></select>';\n  const rem = document.createElement('button');\n  rem.className = 'remover'; rem.textContent = '× remover este antimicrobiano';\n  rem.style.width = '100%'; rem.style.fontSize = '13px';\n  rem.onclick = () => div.remove();\n  div.appendChild(rem);\n  $('listaAtbs').appendChild(div);\n  /* Antibiótico gravado que não está na lista (registro antigo ou digitado em \"Outro\")\n     reabre já em \"Outro\", com o nome preservado no campo de texto. */\n  const selAtb = div.querySelector('.atbNome');\n  const outroAtb = div.querySelector('.atbOutro');\n  const conhecido = dados.atb && ATBS.includes(dados.atb);\n  encherSelect(selAtb, [''].concat(ATBS, [OUTRO_ATB]), conhecido ? dados.atb : (dados.atb ? OUTRO_ATB : ''));\n  /* O texto da opção vazia é só rótulo: sem fixar value='', o próprio rótulo viraria\n     o valor do campo e seria gravado como se fosse o nome de um antibiótico. */\n  selAtb.options[0].textContent = '— escolha o antimicrobiano —';\n  selAtb.options[0].value = '';\n  const alternarOutro = () => {\n    outroAtb.style.display = selAtb.value === OUTRO_ATB ? '' : 'none';\n    if (selAtb.value === OUTRO_ATB) outroAtb.focus();\n  };\n  selAtb.addEventListener('change', alternarOutro);\n  if (dados.atb && !conhecido) outroAtb.value = dados.atb;\n  outroAtb.style.display = selAtb.value === OUTRO_ATB ? '' : 'none';\n  encherSelect(div.querySelector('.atbInd'), IND_ATB, dados.ind);\n  encherSelect(div.querySelector('.atbAval'), AVALIACOES, dados.aval);\n  encherSelect(div.querySelector('.atbRec'), RECOMENDACOES, dados.rec);\n}\n$('maisAtb').onclick = () => adicionarAtb();\n\n/* Nome escolhido na lista, ou o que foi digitado quando a escolha foi \"Outro\". */\nfunction nomeDoAntibiotico(bloco) {\n  const sel = bloco.querySelector('.atbNome');\n  return (sel.value === OUTRO_ATB ? bloco.querySelector('.atbOutro').value : sel.value).trim();\n}\n\n/* O formulário é um só; quando a lista dos leitos está aberta, ele se MOVE para debaixo do\n   paciente escolhido (em vez de ficar lá embaixo, depois de todos os outros) e volta ao\n   lugar original ao salvar/cancelar. O marcador guarda esse lugar. */\nconst marcadorFormulario = document.createComment('lugar do formulário');\n$('formPaciente').before(marcadorFormulario);\nfunction formularioParaOLugar() {\n  if ($('formPaciente').previousSibling !== marcadorFormulario) marcadorFormulario.after($('formPaciente'));\n}\nfunction formularioSob(elemento) {\n  elemento.after($('formPaciente'));\n  $('formPaciente').scrollIntoView({ behavior: 'smooth', block: 'start' });\n}\n\nfunction limparFormulario() {\n  editando = -1;\n  formularioParaOLugar();\n  $('salvar').textContent = 'Salvar paciente';\n  $('cancelar').classList.add('oculto');\n  ['leito', 'prontuario', 'obs'].forEach(id => $(id).value = '');\n  ['temCvc', 'temVm', 'temSvd', 'temAtb', 'temNpt', 'suspeita', 'vmRetirar', 'svdRetirar'].forEach(id => $(id).checked = false);\n  $('blocoFoco').classList.add('oculto');\n  ['Cvc', 'Vm', 'Svd', 'Atb'].forEach(s => $('bloco' + s).classList.add('oculto'));\n  $('listaCateteres').innerHTML = '';\n  $('listaAtbs').innerHTML = '';\n}\n\nfunction carregarNoFormulario(i) {\n  const r = registros[i];\n  editando = i;\n  $('salvar').textContent = 'Atualizar paciente';\n  $('cancelar').classList.remove('oculto');\n  $('leito').value = r.Leito; $('prontuario').value = r.Prontuario; $('obs').value = r.obs || '';\n  $('suspeita').checked = r.suspeita;\n  $('temCvc').checked = r.cateteres.length > 0;\n  $('blocoCvc').classList.toggle('oculto', !r.cateteres.length);\n  $('listaCateteres').innerHTML = '';\n  r.cateteres.forEach(c => adicionarCateter(c.ind, c.retirar));\n  $('temVm').checked = !!r.vm; $('blocoVm').classList.toggle('oculto', !r.vm);\n  if (r.vm) encherSelect($('vmInd'), IND_VM, r.vm);\n  $('vmRetirar').checked = !!r.vmRetirar;\n  $('temSvd').checked = !!r.svd; $('blocoSvd').classList.toggle('oculto', !r.svd);\n  if (r.svd) encherSelect($('svdInd'), IND_SVD, r.svd);\n  $('svdRetirar').checked = !!r.svdRetirar;\n  $('temNpt').checked = !!r.npt;\n  $('blocoFoco').classList.toggle('oculto', !r.suspeita);\n  if (r.foco) encherSelect($('foco'), FOCOS, r.foco);\n  $('temAtb').checked = r.atbs.length > 0;\n  $('blocoAtb').classList.toggle('oculto', !r.atbs.length);\n  $('listaAtbs').innerHTML = '';\n  r.atbs.forEach(a => adicionarAtb(a));\n  $('formPaciente').scrollIntoView({ behavior: 'smooth', block: 'start' });\n}\n\n$('cancelar').onclick = limparFormulario;\n\n$('salvar').onclick = () => {\n  if (!$('leito').value.trim() || !$('prontuario').value.trim()) { alert('Preencha leito e prontuário.'); return; }\n  gravarLocal(CHAVE + '.setor', setorAtual());\n  gravarLocal(CHAVE + '.observador', $('observador').value.trim());\n  const registro = {\n    Leito: $('leito').value.trim(), Prontuario: $('prontuario').value.trim(),\n    cateteres: $('temCvc').checked ? [...$('listaCateteres').children].map(d => ({ ind: d.querySelector('select').value, retirar: d.querySelector('input[type=checkbox]').checked })) : [],\n    vm: $('temVm').checked ? $('vmInd').value : '',\n    vmRetirar: $('temVm').checked && $('vmRetirar').checked,\n    svd: $('temSvd').checked ? $('svdInd').value : '',\n    svdRetirar: $('temSvd').checked && $('svdRetirar').checked,\n    npt: $('temNpt').checked,\n    foco: $('suspeita').checked ? $('foco').value : '',\n    atbs: $('temAtb').checked ? [...$('listaAtbs').querySelectorAll('.bloco')].map(b => ({\n      atb: nomeDoAntibiotico(b), ind: b.querySelector('.atbInd').value,\n      aval: b.querySelector('.atbAval').value, rec: b.querySelector('.atbRec').value\n    })).filter(a => a.atb) : [],\n    suspeita: $('suspeita').checked, obs: $('obs').value.trim(),\n    exportadoEm: editando >= 0 ? null : null\n  };\n  if (editando >= 0) registros[editando] = { ...registros[editando], ...registro, exportadoEm: null };\n  else registros.push(registro);\n  limparFormulario();\n  gravar();\n};\n\nfunction gravar() { gravarLocal(CHAVE, JSON.stringify(registros)); conferirArmazenamento(); desenhar(); }\n\nfunction desenhar() {\n  const lista = $('lista');\n  lista.innerHTML = '';\n  registros.forEach((r, i) => {\n    const div = document.createElement('div');\n    div.className = 'item';\n    const selos = [];\n    if (r.cateteres.length) selos.push('CVC×' + r.cateteres.length);\n    if (r.vm) selos.push('VM');\n    if (r.svd) selos.push('SVD');\n    if (r.atbs.length) selos.push('ATB×' + r.atbs.length);\n    if (r.npt) selos.push('NPT');\n    if (r.cateteres.some(x => x.retirar) || r.vmRetirar || r.svdRetirar) selos.push('RETIRAR');\n    if (r.suspeita) selos.push('SUSPEITA' + (r.foco ? ': ' + r.foco : ''));\n    div.innerHTML = `<strong>Leito ${r.Leito}</strong> · ${r.Prontuario} <span class=\"selos\">${selos.map(s => `<span>${s}</span>`).join('')}${r.exportadoEm ? '<span class=\"enviado\">enviado</span>' : ''}</span><span class=\"suave\"> toque para editar</span>`;\n    const btn = document.createElement('button');\n    btn.className = 'excluir'; btn.textContent = 'excluir';\n    btn.onclick = e => { e.stopPropagation(); registros.splice(i, 1); if (editando === i) limparFormulario(); gravar(); };\n    div.prepend(btn);\n    div.onclick = () => { formularioParaOLugar(); carregarNoFormulario(i); };\n    lista.appendChild(div);\n  });\n  $('resumo').textContent = registros.length + ' pacientes registrados';\n}\n\nfunction csvCampo(v) { v = String(v == null ? '' : v); return /[;\"\\n]/.test(v) ? '\"' + v.replace(/\"/g, '\"\"') + '\"' : v; }\nfunction tabelaCSV(nome, objetos) {\n  let saida = '##' + nome + '\\n';\n  if (!objetos.length) return saida;\n  const colunas = Object.keys(objetos[0]);\n  saida += colunas.join(';') + '\\n';\n  saida += objetos.map(o => colunas.map(c => csvCampo(o[c])).join(';')).join('\\n') + '\\n';\n  return saida;\n}\nfunction avisar(texto, erro) {\n  let el = document.getElementById('statusExporte');\n  if (!el) {\n    el = document.createElement('p');\n    el.id = 'statusExporte';\n    document.getElementById('exportar').after(el);\n  }\n  el.style.cssText = 'font-weight:600;font-size:14px;margin-top:8px;color:' + (erro ? '#b03a2e' : '#0d3f7a');\n  el.textContent = texto;\n}\nasync function entregarArquivo(nome, texto) {\n  if (ENVIO_URL) {\n    try {\n      await fetch(ENVIO_URL, { method: 'POST', mode: 'no-cors', headers: { 'Content-Type': 'text/plain' },\n        body: JSON.stringify({ segredo: ENVIO_SEGREDO, nome: nome, conteudo: texto }) });\n      avisar('Enviado para a pasta da CCIH no Drive: ' + nome);\n      return true;\n    } catch (e) {\n      avisar('Sem conexão para o envio direto — salvando o arquivo para enviar por e-mail.', true);\n    }\n  }\n  try {\n    /* Blob + createObjectURL, e não data: URI: o celular bloqueia o download de data:\n       quando o arquivo passa de alguns KB, e a exportação falhava calada. */\n    const blob = new Blob(['﻿' + texto], { type: 'text/csv;charset=utf-8' });\n    const url = URL.createObjectURL(blob);\n    const a = document.createElement('a');\n    a.href = url;\n    a.download = nome;\n    document.body.appendChild(a); a.click(); a.remove();\n    setTimeout(() => URL.revokeObjectURL(url), 60000);\n    avisar('Arquivo \"' + nome + '\" salvo na pasta Downloads.');\n    /* O e-mail fica num botão para o usuário tocar: disparar duas navegações seguidas\n       (download + mailto) faz o celular cancelar uma das duas. */\n    const status = document.getElementById('statusExporte');\n    const email = document.createElement('a');\n    email.href = 'mailto:' + EMAIL_DESTINO + '?subject=' + encodeURIComponent('CCIH — ' + nome)\n      + '&body=' + encodeURIComponent('Segue em anexo o arquivo ' + nome + ' (anexe-o pela pasta Downloads).');\n    email.textContent = '✉ Abrir e-mail para ' + EMAIL_DESTINO + ' (anexe o arquivo baixado)';\n    email.style.cssText = 'display:block;margin-top:8px;padding:10px;border:1px solid #0d3f7a;border-radius:8px;'\n      + 'color:#0d3f7a;font-weight:700;text-align:center;text-decoration:none';\n    status.appendChild(email);\n    const baixar = document.createElement('a');\n    baixar.href = url;\n    baixar.download = nome;\n    baixar.textContent = '↓ Baixar de novo';\n    baixar.style.cssText = 'display:block;margin-top:6px;color:#61707f;font-size:13px;text-align:center';\n    status.appendChild(baixar);\n    return true;\n  } catch (e) {\n    avisar('Não foi possível exportar: ' + e.message, true);\n    return false;\n  }\n}\nfunction montarPacote() {\n  const base = { Data: $('data').value, Setor: setorAtual(), CriadoPor: $('observador').value.trim() };\n  const agora = new Date().toISOString().slice(0, 16).replace('T', ' ');\n  const visitas = registros.map(r => ({\n    Data: base.Data, Setor: base.Setor, Leito: r.Leito, Prontuario: r.Prontuario,\n    CVC: r.cateteres.length ? 'S' : 'N', CVC_Qtd: String(r.cateteres.length || ''),\n    CVC_Indicacoes: r.cateteres.map(c => c.ind + (c.retirar ? ' [retirar]' : '')).join(' | '),\n    CVC_Retirar: r.cateteres.length ? (r.cateteres.some(c => c.retirar) ? 'S' : 'N') : '',\n    VM: r.vm ? 'S' : 'N', VM_Indicacao: r.vm, VM_Retirar: r.vm ? (r.vmRetirar ? 'S' : 'N') : '',\n    SVD: r.svd ? 'S' : 'N', SVD_Indicacao: r.svd, SVD_Retirar: r.svd ? (r.svdRetirar ? 'S' : 'N') : '',\n    NPT: r.npt ? 'S' : 'N',\n    SuspeitaIRAS: r.suspeita ? 'S' : 'N', FocoSuspeito: r.foco || '', Observacoes: r.obs,\n    CriadoPor: base.CriadoPor, CriadoEm: agora\n  }));\n  const avaliacoes = [];\n  registros.forEach(r => r.atbs.forEach(a => avaliacoes.push({\n    Data: base.Data, Setor: base.Setor, Leito: r.Leito, Prontuario: r.Prontuario,\n    Antibiotico: a.atb, Indicacao: a.ind, Avaliacao: a.aval, Recomendacao: a.rec,\n    CriadoPor: base.CriadoPor, CriadoEm: agora\n  })));\n  return '##ccih-miniapp;tipo=uti;versao=3\\n' + tabelaCSV('visitas', visitas) + tabelaCSV('avaliacoes_atb', avaliacoes);\n}\n\n$('exportar').onclick = async () => {\n  if (!registros.length) { avisar('Nenhum registro para exportar.', true); return; }\n  const setor = (setorAtual() || 'UTI').replace(/[^A-Za-z0-9]+/g, '-');\n  const nome = `UTI_${setor}_${$('data').value}.csv`;\n  if (await entregarArquivo(nome, montarPacote())) {\n    registros.forEach(r => r.exportadoEm = Date.now());\n    gravar();\n    anonimizarLista();\n  }\n};\n$('limpar').onclick = () => { if (confirm('Apagar todos os registros deste aparelho?')) { registros = []; limparFormulario(); gravar(); } };\ndesenhar();\n\n/* ---- Lista dos leitos de hoje (versão gerada pelo aplicativo) ----\n   O aplicativo da CCIH gera esta mesma página com a lista dos pacientes internados no setor\n   (nome, leito, prontuário, última evolução médica, sinais vitais alterados) CIFRADA com\n   senha (AES-GCM, chave derivada por PBKDF2) — o arquivo pode circular que ninguém lê sem\n   a senha. Decifrada, a lista fica só na memória da página, nunca no armazenamento do\n   aparelho. Sem CIFRADO (versão pública), nada disto aparece e o miniapp é o de sempre. */\nconst LISTA_CIFRADA = typeof CIFRADO !== 'undefined' ? CIFRADO : null;\nconst META_LISTA = typeof META !== 'undefined' ? META : {};\nlet listaPacientes = [];\nfunction deBase64(b64) {\n  const bin = atob(b64), u8 = new Uint8Array(bin.length);\n  for (let i = 0; i < bin.length; i++) u8[i] = bin.charCodeAt(i);\n  return u8;\n}\nif (LISTA_CIFRADA) {\n  const idadeHoras = (Date.now() - new Date(META_LISTA.geradoEm).getTime()) / 3600000;\n  $('telaSenha').classList.remove('oculto');\n  $('infoLista').textContent = (META_LISTA.setor ? META_LISTA.setor + ' · ' : '') + 'dados extraídos em '\n    + new Date(META_LISTA.geradoEm).toLocaleString('pt-BR') + (idadeHoras > (META_LISTA.avisoHoras || 48) ? ' — atenção: mais de ' + Math.round(idadeHoras) + ' h' : '');\n  if (idadeHoras > (META_LISTA.bloqueioDias || 7) * 24) {\n    $('telaSenha').innerHTML = '<strong>Esta lista tem mais de ' + (META_LISTA.bloqueioDias || 7) + ' dias e foi bloqueada por segurança.</strong><p class=\"suave\">Peça à CCIH uma versão atualizada. O formulário abaixo continua funcionando normalmente.</p>';\n  } else {\n    $('abrirLista').onclick = abrirLista;\n    $('senha').addEventListener('keydown', e => { if (e.key === 'Enter') abrirLista(); });\n  }\n  if (META_LISTA.setor) restaurarSetor(META_LISTA.setor);\n}\nasync function abrirLista() {\n  try {\n    const material = await crypto.subtle.importKey('raw', new TextEncoder().encode($('senha').value), 'PBKDF2', false, ['deriveKey']);\n    const chave = await crypto.subtle.deriveKey(\n      { name: 'PBKDF2', salt: deBase64(LISTA_CIFRADA.sal), iterations: 150000, hash: 'SHA-256' },\n      material, { name: 'AES-GCM', length: 256 }, false, ['decrypt']);\n    const aberto = await crypto.subtle.decrypt({ name: 'AES-GCM', iv: deBase64(LISTA_CIFRADA.iv) }, chave, deBase64(LISTA_CIFRADA.dados));\n    listaPacientes = JSON.parse(new TextDecoder().decode(aberto)).pacientes || [];\n    $('telaSenha').classList.add('oculto');\n    $('cartaoLista').classList.remove('oculto');\n    desenharLista();\n  } catch (e) {\n    $('erroSenha').textContent = 'Senha incorreta.';\n  }\n}\nfunction selo(texto, alerta) {\n  const s = document.createElement('span');\n  s.textContent = texto;\n  s.style.cssText = 'display:inline-block;border-radius:10px;padding:2px 8px;font-size:12px;margin:2px 4px 0 0;'\n    + (alerta ? 'background:#fbe9e7;color:#b03a2e;font-weight:600' : 'background:#e7effb;color:#0d3f7a');\n  return s;\n}\n/* Depois do envio (pedido de 03/10/2026), a lista aberta na tela perde o que identifica a\n   pessoa: nome, texto da evolução e sinais — ficam leito, prontuário, setor, dias e as\n   marcas da visita. O arquivo em si continua cifrado; para ver nome de novo é reabrir e\n   digitar a senha. Nada disto jamais passou pelo armazenamento do aparelho. */\nlet listaAnonimizada = false;\nfunction anonimizarLista() {\n  if (!listaPacientes.length) return;\n  listaPacientes.forEach(p => {\n    p.nome = ''; p.ultimaEvolucaoMedica = null; p.sinaisInfeccao = ''; p.vitais = [];\n    p.isolamento = p.isolamento ? 'isolamento' : ''; p.irasAberta = p.irasAberta ? 'IRAS em investigação' : '';\n  });\n  listaAnonimizada = true;\n  desenharLista();\n}\nfunction desenharLista() {\n  const alvo = $('listaPacientes');\n  alvo.innerHTML = '';\n  const avaliados = new Set(registros.map(r => String(r.Prontuario).replace(/\\D/g, '')));\n  $('resumoLista').textContent = '— ' + listaPacientes.length + ' leito(s) · ' + listaPacientes.filter(p => avaliados.has(String(p.prontuario).replace(/\\D/g, ''))).length + ' já avaliado(s)'\n    + (listaAnonimizada ? ' · enviado: nomes e evoluções removidos desta tela (reabra o arquivo com a senha para vê-los)' : '');\n  listaPacientes.forEach(p => {\n    const feito = avaliados.has(String(p.prontuario).replace(/\\D/g, ''));\n    const div = document.createElement('div');\n    div.className = 'item';\n    div.style.cursor = 'default';\n    const cab = document.createElement('div');\n    cab.style.cssText = 'display:flex;align-items:baseline;gap:8px;flex-wrap:wrap';\n    const leito = document.createElement('strong'); leito.textContent = 'Leito ' + (p.leito || '?'); leito.style.fontSize = '16px';\n    const nome = document.createElement('span'); nome.textContent = p.nome || (listaAnonimizada ? '' : '(sem nome no cadastro)');\n    const num = document.createElement('span'); num.className = 'suave'; num.textContent = 'pront. ' + p.prontuario + (p.dias != null ? ' · ' + p.dias + ' d' : '');\n    cab.append(leito, nome, num);\n    const selos = document.createElement('div');\n    (p.dispositivos || []).forEach(d => selos.appendChild(selo(d)));\n    (p.antibioticos || []).forEach(a => selos.appendChild(selo('💊 ' + a)));\n    if (p.culturasPendentes) selos.appendChild(selo('🧫 ' + p.culturasPendentes + ' cultura(s) pendente(s)'));\n    if (p.isolamento) selos.appendChild(selo('🚧 ' + p.isolamento, true));\n    if (p.irasAberta) selos.appendChild(selo('🩺 IRAS em investigação: ' + p.irasAberta, true));\n    if (p.sinaisInfeccao) selos.appendChild(selo('⚠ evolução sugere: ' + p.sinaisInfeccao, true));\n    (p.vitais || []).forEach(v => selos.appendChild(selo('📈 ' + v.sinal + ' (' + v.data.slice(5).split('-').reverse().join('/') + ')', true)));\n    div.append(cab, selos);\n    if (p.ultimaEvolucaoMedica) {\n      const det = document.createElement('details');\n      const sum = document.createElement('summary');\n      sum.className = 'suave';\n      sum.textContent = 'Última evolução médica — ' + p.ultimaEvolucaoMedica.data.split('-').reverse().join('/') + (p.ultimaEvolucaoMedica.autor ? ' · ' + p.ultimaEvolucaoMedica.autor : '');\n      const txt = document.createElement('p');\n      txt.className = 'suave'; txt.style.whiteSpace = 'pre-wrap'; txt.textContent = p.ultimaEvolucaoMedica.texto;\n      det.append(sum, txt);\n      div.appendChild(det);\n    } else {\n      const s = document.createElement('p'); s.className = 'suave'; s.textContent = 'sem evolução médica na foto do Tasy'; div.appendChild(s);\n    }\n    const btn = document.createElement('button');\n    btn.className = feito ? 'secundario' : 'principal';\n    btn.textContent = feito ? '✓ avaliado — editar' : 'Avaliar este paciente';\n    btn.style.marginTop = '6px';\n    btn.onclick = () => {\n      const i = registros.findIndex(r => String(r.Prontuario).replace(/\\D/g, '') === String(p.prontuario).replace(/\\D/g, ''));\n      if (i >= 0) { carregarNoFormulario(i); formularioSob(div); return; }\n      limparFormulario();\n      $('leito').value = p.leito || '';\n      $('prontuario').value = p.prontuario || '';\n      /* Dispositivos registrados no aplicativo já vêm marcados — a enfermeira só confirma. */\n      const temDisp = sigla => (p.dispositivos || []).some(d => new RegExp('^' + sigla + '\\\\b', 'i').test(d));\n      if (temDisp('CVC')) { $('temCvc').checked = true; $('blocoCvc').classList.remove('oculto'); if (!$('listaCateteres').children.length) adicionarCateter(); }\n      if (temDisp('VM')) { $('temVm').checked = true; $('blocoVm').classList.remove('oculto'); }\n      if (temDisp('SVD')) { $('temSvd').checked = true; $('blocoSvd').classList.remove('oculto'); }\n      /* Antibióticos em curso (pelo aplicativo) já entram para avaliação — \"Meropenem D4\"\n         vira um bloco de avaliação do Meropenem; só falta indicação, avaliação e conduta. */\n      const emCurso = (p.antibioticos || []).map(a => String(a).replace(/\\s+D\\d+$/i, '').trim()).filter(Boolean);\n      if (emCurso.length) {\n        $('temAtb').checked = true; $('blocoAtb').classList.remove('oculto');\n        $('listaAtbs').innerHTML = '';\n        emCurso.forEach(atb => adicionarAtb({ atb }));\n      }\n      formularioSob(div);\n    };\n    div.appendChild(btn);\n    alvo.appendChild(div);\n  });\n}\n/* Quando um paciente é salvo, a lista marca o leito como avaliado. */\nconst gravarOriginal = gravar;\ngravar = function () { gravarOriginal(); if (listaPacientes.length) desenharLista(); };\n</script>\n</body>\n</html>\n"};
const VISITA_UTI_MODELO = MINIAPPS_MODELOS['visita-uti.html'];
if (typeof module !== 'undefined' && module.exports) module.exports = { MINIAPPS_MODELOS, VISITA_UTI_MODELO };
